INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3801', 'spa', 'Túnica, vestidura: la prenda principal de largo corporal usada sobre la piel en el uso cotidiano, sacerdotal y ceremonial.', 'Túnica, vestidura: la prenda principal de largo corporal usada sobre la piel en el uso cotidiano, sacerdotal y ceremonial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3802', 'spa', 'Hombro (parte del cuerpo); lado o ladera de un accidente geográfico o estructura; hombrera del efod sacerdotal.', 'Hombro (parte del cuerpo); lado o ladera de un accidente geográfico o estructura; hombrera del efod sacerdotal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3803', 'spa', 'Rodear, cercar; por extensión, coronar o adornar; también esperar (influencia aramea).', 'כָּתַר es un verbo de cerco cuyas acepciones irradian desde la imagen central de cerrar un anillo alrededor de alguien. En Jueces 20:43, las fuerzas israelitas rodearon a los benjaminitas; en Salmo 22:12, toros poderosos de Basán cercan al salmista sufriente. El Hifil en Proverbios 14:18 transforma el cerco hostil en coronación: los prudentes «se coronan de» conocimiento. Lo más inesperado es Job 36:2, donde Elihú usa כָּתַר en el sentido arameo de «espérame un poco», reflejando el carácter arameizante de los discursos de Elihú.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3804', 'spa', 'Corona real, diadema usada por reyes y reinas persas', 'Término para la corona ornamentada que portaba la realeza persa, que aparece exclusivamente en el libro de Ester. La «corona real» (כֶּתֶר מַלְכוּת) simboliza autoridad y honor: Vasti es convocada llevándola para exhibir su belleza, Ester la recibe al ser proclamada reina, y Mardoqueo imagina a Amán honrado con la corona del rey sobre un caballo real. Este préstamo lingüístico persa refleja el ambiente cortesano aqueménida propio de la narrativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3805', 'spa', 'Capitel de columna: la corona ornamental en la parte superior de una columna, especialmente los pilares del templo Jaquín y Boaz.', 'Capitel de columna: la corona ornamental en la parte superior de una columna, especialmente los pilares del templo Jaquín y Boaz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3807', 'spa', 'Golpear, machacar, destrozar; pulverizar a golpes, forjar martillando, o derrotar militarmente', 'Golpear, machacar, destrozar; pulverizar a golpes, forjar martillando, o derrotar militarmente');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3808', 'spa', 'No; partícula negativa objetiva que niega verbos, cláusulas y aserciones; también retórica y como rechazo independiente.', 'La partícula fundamental de la negación hebrea, לֹא niega la realidad y no la voluntad (a diferencia de אַל, que prohíbe). Con más de 5.000 apariciones, niega verbos (''no hizo''), adjetivos (''no es bueno'') y cláusulas enteras. Su fuerza retórica se manifiesta en los centenares de preguntas con הֲלֹא — ''¿Acaso no...?''— que esperan una respuesta afirmativa y poseen fuerza persuasiva (Gn 4:7; 13:9). Combinada con preposiciones forma ''sin'' (Nm 35:22), y usada de manera independiente se convierte en el rotundo rechazo ''¡No!'' (Gn 18:15; 19:2). Toda lengua refleja este abanico: español ''no'', francés ''pas/non'', alemán ''nicht/nein''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3809', 'spa', 'No — la partícula negativa estándar del arameo que niega verbos, participios y cláusulas; usada una vez como sustantivo con el sentido de ''nada''.', 'No — la partícula negativa estándar del arameo que niega verbos, participios y cláusulas; usada una vez como sustantivo con el sentido de ''nada''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3810', 'spa', 'Lo-debar, una ciudad en Galaad al este del río Jordán', 'Un asentamiento en la región transjordana de Galaad, posiblemente al este o noreste de Mahanaim. El nombre parece significar «sin pasto» o «sin cosa», quizá una etimología popular o un juego de palabras. Mefiboset, hijo de Jonatán, se refugió allí tras la caída de la casa de Saúl. Más tarde, durante la rebelión de Absalón, un benefactor de Lo-debar llevó provisiones a David en Mahanaim, lo que sugiere una comunidad leal a la casa davídica pese a haber cobijado al descendiente de Saúl.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3811', 'spa', 'Estar o volverse cansado, agotado; en el Hifil, cansar o agotar a alguien', 'Estar o volverse cansado, agotado; en el Hifil, cansar o agotar a alguien');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3812', 'spa', 'Lea — primera esposa de Jacob e hija mayor de Labán, madre de seis tribus de Israel', 'Lea — primera esposa de Jacob e hija mayor de Labán, madre de seis tribus de Israel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3816', 'spa', 'Pueblo, nación — término poético para comunidades étnicas o tribales, frecuentemente en paralelo con gôy y ʿam', 'Pueblo, nación — término poético para comunidades étnicas o tribales, frecuentemente en paralelo con gôy y ʿam');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3820a', 'spa', 'Corazón; el ser interior como sede del pensamiento, la voluntad, la emoción y la conciencia; también el centro físico de algo.', 'Mucho más rico de lo que sugiere la palabra española ''corazón,'' לֵב es el término hebreo integral para la vida interior de una persona: mente, voluntad, emociones, conciencia y carácter moral, todo a la vez. Cuando Éx 28:3 habla de los ''sabios de corazón,'' la palabra denota habilidad intelectual y entendimiento, no sentimentalismo. El francés coeur y el alemán Herz poseen una amplitud semejante, pero el cognado árabe قَلْب hace especialmente clara la doble fuerza: sirve tanto para el órgano físico como para la sede de la intención. En una extensión espacial, la misma palabra designa ''el corazón del mar'' (Éx 15:8) o ''el corazón de la encina'' (2 S 18:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3823a', 'spa', 'Obtener entendimiento, cautivar o robar el corazón', 'Verbo denominativo de לֵבָב (corazón), empleado en dos sentidos bien distintos. En Job 11:12, el Niphal significa ''adquirir entendimiento'': ¿acaso un hombre hueco llegará a tener cordura? En Cantares 4:9, el Piel expresa ''me has robado el corazón'', la apasionada declaración del amante a su amada. Este doble uso refleja cómo el corazón abarca tanto el intelecto como el afecto en el pensamiento hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3824', 'spa', 'Corazón, ser interior; sede del pensamiento, la voluntad, la emoción y el carácter moral; raramente, el centro físico.', 'לֵבָב es la forma más plena y estilísticamente variante de לֵב, y al igual que su gemelo más breve, designa mucho más que el órgano que bombea sangre. En el pensamiento hebreo, el לֵבָב es donde una persona piensa, decide, desea y se orienta moralmente: el centro unificado de la conciencia que el español debe repartir torpemente entre ''mente,'' ''voluntad,'' ''corazón'' y ''conciencia.'' El mandamiento del Shemá de amar a Dios ''con todo tu לֵבָב'' (Dt 6:5) se dirige a la persona interior completa, no solo a la emoción. Casi todas sus 252 ocurrencias portan este significado de ser interior, lo que lo convierte en uno de los sustantivos teológicamente más concentrados de las Escrituras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3825', 'spa', 'lebab (arameo) -- corazón, mente; sede interior del pensamiento, la voluntad y la emoción en el arameo bíblico', 'El sustantivo arameo לְבַב corresponde exactamente al mucho más frecuente hebreo לֵב/לֵבָב, designando el corazón como sede del intelecto, la voluntad y la emoción. Sus siete apariciones se limitan a los capítulos arameos de Daniel, donde describe la vida interior de reyes y experiencias visionarias. Nabucodonosor recibe un corazón de animal en lugar de uno humano (Dan 4:16), imagen vívida del trastorno mental, y después su corazón se ''enaltece'' por orgullo (Dan 5:20). Daniel interpreta los pensamientos secretos del rey, ''los pensamientos de tu corazón'' (Dan 2:30). En Dan 7:4, la bestia recibe ''un corazón de hombre''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3826', 'spa', 'libbah — corazón(es); variante femenina/plural de leb, la persona interior de pensamiento, voluntad y carácter moral', 'El sustantivo libbah es una variante femenina y plural de la palabra hebrea común para corazón (leb), que designa la persona interior como sede del carácter moral, la intención y el pensamiento. Sus siete apariciones se concentran en textos sapienciales y poéticos donde el corazón es escudriñado por Dios o revelado mediante la conducta. Proverbios 15:11 afirma que el Seol y el Abadón están abiertos ante el SEÑOR: «¡cuánto más los corazones de los hijos de los hombres!». Proverbios 17:3 compara la prueba divina de los corazones con el crisol del refinador. Los Salmos piden a Dios que examine los corazones de los justos (Sal 7:9) y bendiga a los rectos de corazón (Sal 125:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3828', 'spa', 'Incienso: la resina aromática blanca quemada en el culto israelita, las ofrendas de grano y el incienso sagrado', 'Incienso: la resina aromática blanca quemada en el culto israelita, las ofrendas de grano y el incienso sagrado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3830', 'spa', 'Vestido, ropa o vestidura; lo que se lleva puesto, tanto literal como figuradamente para dignidad o condición', 'Vestido, ropa o vestidura; lo que se lleva puesto, tanto literal como figuradamente para dignidad o condición');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3832', 'spa', 'Ser derribado, arruinado o destruido (Niphal)', 'Verbo que expresa ser violentamente derribado o llevado a la ruina, presente en contextos sapienciales y proféticos. Proverbios advierte que el necio de labios será derribado: la lengua desenfrenada conduce a la caída. Oseas pronuncia que un pueblo sin entendimiento será destruido, vinculando la ceguera espiritual e intelectual con la destrucción inevitable. La raíz transmite un colapso forzoso y a menudo irreversible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3833c', 'spa', 'Leona, gran leon — termino poetico para la hembra o el leon en su madurez, usado en profecia y bendicion', 'El sustantivo לָבִיא (lavi) designa una leona o, mas ampliamente, un gran leon en su plenitud, y pertenece al rico vocabulario hebreo para los leones (junto con אַרְיֵה, כְּפִיר, לַיִשׁ, שַׁחַל). Aparece casi exclusivamente en poesia elevada y discurso profetico. Jacob bendice a Juda como cachorro de leon que se agazapa como un lavi (Gn 49:9). Balaam compara a Israel con un lavi que se levanta y no se echa hasta devorar su presa (Nm 23:24; 24:9). Moises asemeja a Dan a un cachorro de leon que salta desde Basan (Dt 33:20). Los profetas evocan la imagen tanto para el juicio como para el terror (Is 5:29; 30:6; Os 13:8; Jl 1:6; Nah 2:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3834', 'spa', 'Tortas, pasteles en forma de corazón o frituras', 'Tipo de torta o pastel, posiblemente en forma de corazón (relacionado con לֵבָב, corazón) o frito en sartén. El término aparece únicamente en el relato de la enfermedad fingida de Amnón, quien pide que Tamar prepare estas tortas especiales delante de él. Este detalle culinario doméstico e íntimo crea una tensión trágica, pues se convierte en el escenario de la violencia. La preparación ''ante sus ojos'' sugiere una técnica visible y elaborada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3835a', 'spa', 'Ser blanco, volverse blanco; blanquear o purificar, tanto en sentido fisico como de limpieza etica y moral.', 'Verbo hebreo que significa ''ser o volverse blanco'', extendiendose figuradamente a la purificacion moral. En su forma causativa Hifil abarca un rango notable: Dios promete que los pecados ''aunque sean como la grana, se volveran blancos como la nieve'' (Is 1:18), y el salmista suplica ser limpiado hasta ''quedar mas blanco que la nieve'' (Sal 51:7). Daniel lo emplea para la purificacion escatologica: ''muchos se purificaran y se emblanqueceran'' (Dn 11:35; 12:10). Incluso la naturaleza participa: Joel 1:7 describe una plaga de langostas que deja las ramas ''mostrando su blancura''. Las traducciones al espanol ''blanquearon'' y ''seran blancos'' distinguen nitidamente entre el estado cumplido y el prometido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3835b', 'spa', 'Hacer ladrillos, trabajar como ladrillero', 'Verbo denominativo de לְבֵנָה (ladrillo), que describe la fabricación de ladrillos de barro, el material de construcción principal en la antigua Mesopotamia y Egipto. Génesis conserva la determinación de los constructores de Babel: ''¡Hagamos ladrillos!'' Éxodo registra el cruel decreto del Faraón de retirar la paja de las cuotas israelitas sin reducir la producción exigida. El proceso incluía mezclar barro con paja, moldear y secar al sol, labor intensiva propia de pueblos esclavizados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3836', 'spa', 'Blanco: el adjetivo de color que describe piel, cabello, animales, vestiduras y piedras a lo largo de las Escrituras.', 'Blanco: el adjetivo de color que describe piel, cabello, animales, vestiduras y piedras a lo largo de las Escrituras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3837a', 'spa', 'Labán — el patriarca arameo, hermano de Rebeca y suegro de Jacob.', 'Labán — el patriarca arameo, hermano de Rebeca y suegro de Jacob.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3841', 'spa', 'Libná: una ciudad cananea en la Sefela de Judá; también un campamento en la ruta del éxodo por el desierto', 'Libná: una ciudad cananea en la Sefela de Judá; también un campamento en la ruta del éxodo por el desierto');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3842', 'spa', 'Luna, el astro lunar (término poético)', 'Término poético para la luna, empleado en contextos elevados, a menudo proféticos o románticos. Isaías vislumbra la renovación escatológica cuando la luz de la luna igualará el resplandor del sol. También profetiza que la luna será avergonzada cuando YHWH reine en el monte Sion con gloria. En Cantares, la belleza de la amada se compara con la luna: hermosa, luminosa, imponente. Este vocablo posee mayor peso lírico que el término común יָרֵחַ.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3843', 'spa', 'Ladrillo, baldosa — bloque de arcilla moldeado, secado o cocido para construccion; asociado con trabajo forzado y soberbia', 'El sustantivo לְבֵנָה (levenah) significa ladrillo o baldosa — un bloque de arcilla secado al sol o cocido en horno, usado como material de construccion fundamental en todo el antiguo Cercano Oriente. Su primera aparicion es en la narrativa de la Torre de Babel, donde los hombres dicen ''hagamos ladrillos'' (נִלְבְּנָה לְבֵנִים, Gn 11:3), vinculando este material con la soberbia colectiva. En Exodo, la fabricacion de ladrillos se convierte en la imagen definitoria de la esclavitud israelita: el faraon exige ladrillos sin paja (Ex 1:14; 5:7-19). Isaias contrasta los humildes ladrillos con la piedra labrada (Is 9:9) y condena a quienes queman incienso sobre ladrillos (Is 65:3). Ezequiel usa un ladrillo como maqueta de asedio en miniatura (Ez 4:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3844', 'spa', 'Líbano — la cadena montañosa boscosa al norte de Israel, célebre por sus cedros y acantilados nevados.', 'Líbano — la cadena montañosa boscosa al norte de Israel, célebre por sus cedros y acantilados nevados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3845', 'spa', 'Libni; levita, hijo de Gerson hijo de Levi, ancestro eponimo de un clan levitico que lleva su nombre.', 'Nombre propio masculino que significa ''blanco'' (de la raiz לבן), llevado por un nieto de Levi a traves de la linea de Gerson. Libni aparece en las listas genealogicas como primogenito de Gerson (Ex 6:17; Nm 3:18), y sus descendientes se rastrean en las genealogias leviticas ampliadas del Cronista (1 Cr 6:17, 20, 29). El clan patronimico ''los libnitas'' (Nm 3:21; 26:58) deriva de su nombre. Todas las traducciones principales — ingles ''Libni'', espanol ''Libni'', frances y aleman igualmente — transliteran sin variacion, reflejando la transmision directa de este nombre levitico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3847', 'spa', 'Ponerse o llevar una prenda; causativamente, vestir a alguien; como participio, estar vestido de; en pasivo, haber sido ataviado.', 'El verbo hebreo primario para el acto de vestirse, que cubre toda la gama desde ponerse las propias prendas hasta vestir a otra persona. En el Qal describe la acción simple de ponerse ropa: ya sean vestiduras sacerdotales (Lv 6:10), ropas reales (Gn 38:19) o las metafóricas vestiduras de salvación. El Hifil causativo es teológicamente rico: Dios mismo viste a Adán y Eva con túnicas de piel (Gn 3:21) y el faraón viste a José de lino fino (Gn 41:42). El participio funciona casi como adjetivo, describiendo a alguien como ''vestido de'' determinadas prendas, frecuentemente en visiones proféticas (Ez 9:2). Los cognados se extienden por toda la familia semítica: arameo levish, árabe labisa, etiópico lebsa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3848', 'spa', 'vestir, revestir (verbo arameo usado en Daniel 5 para la investidura ceremonial de púrpura)', 'Verbo arameo que aparece exclusivamente en Daniel 5, en el contexto de los honores reales prometidos a quien interpretara la escritura en el muro. El rey promete que el intérprete será revestido de púrpura, color que simbolizaba la realeza y el alto cargo en la corte persa. La forma Hafel (causativa) en el versículo 29 describe la investidura efectiva cuando Daniel es vestido de púrpura. Este acto refleja la vestimenta ceremonial babilónica y persa como signo de otorgamiento de rango.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3849', 'spa', 'Log; pequena medida de liquidos (aprox. medio litro), usada exclusivamente para aceite en el ritual de purificacion del leproso.', 'Sustantivo masculino que designa una pequena unidad de medida para liquidos, equivalente a un doceavo de hin o aproximadamente medio litro. El log aparece exclusivamente en Levitico 14, el detallado ritual para purificar a un leproso sanado, donde siempre mide aceite de oliva (Lv 14:10, 12, 15, 21, 24). El sacerdote toma un log de aceite, rocía parte de el ante el Senor y unge a la persona purificada. Su contexto tan restringido — cinco apariciones todas en un solo capitulo — lo convierte en uno de los terminos mas especializados de la metrologia biblica. El cognado arameo lugga y el siriaco lagga confirman su antiguedad como medida estandar en las culturas semiticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3850', 'spa', 'Lod (Lida), ciudad en el territorio de Benjamín, actual Ludd cerca de Tel Aviv', 'Lod fue una ciudad edificada por los benjaminitas tras la conquista, situada a unos dieciocho kilómetros al sureste de Jaffa en el camino a Jerusalén. En los períodos helenístico y romano llegó a conocerse como Lida, la ciudad donde Pedro sanó a Eneas y donde muchos creyeron en el Señor. Los censos postexílicos muestran que la ciudad fue repoblada por los exiliados que regresaron. La moderna Ludd conserva el antiguo nombre y ubicación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3851', 'spa', 'Llama o resplandor de fuego; hoja o filo reluciente de un arma', 'El sustantivo לַהַב capta el borde brillante y peligroso tanto del fuego como del metal. En la mayoría de sus apariciones designa una llama o llamarada, especialmente en contextos de teofanía y juicio divino: la llama que asciende del altar de Manoa (Jue 13:20), el fuego devorador de la ira de Dios (Isa 29:6; 30:30) y la vorágine de fuego que Joel compara con un enjambre de langostas (Joel 2:5). Su sentido secundario es la hoja o filo centelleante de un arma, ilustrado vívidamente cuando la hoja entera de Ehud se hunde en el vientre de Eglón (Jue 3:22) y cuando el destello de una lanza reluce en la batalla (Job 39:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3852', 'spa', 'Llama o llamarada de fuego, ya sea literal o figurada; también la hoja reluciente de un arma', 'Llama o llamarada de fuego, ya sea literal o figurada; también la hoja reluciente de un arma');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3857', 'spa', 'Arder, llamear; (Piel) abrasar, incendiar, consumir con fuego', 'Verbo de fuego e intensidad que describe tanto el estado de estar en llamas como la acción de prender fuego a algo. En su forma Qal retrata seres o cosas que arden o llamean: el fuego convertido en ministros de Dios (Sal 104:4) y enemigos cuyas lenguas son como fuego abrasador (Sal 57:4). En el Piel, más frecuente, el verbo se vuelve transitivo y devastador: el fuego encendido por la ira de Dios que abrasa los cimientos de los montes (Dt 32:22), llamas que consumen pastizales (Joel 1:19; 2:3) y fuego que rodea a los impíos (Sal 97:3; 106:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3860', 'spa', 'por tanto, por esta razón (partícula poco frecuente)', 'Partícula poco frecuente que significa «por tanto» o «por esta razón», presente en Rut y posiblemente en Job. En Rut 1:13, Noemí la emplea dos veces en sus amargas preguntas retóricas: ¿acaso esperarían a que crecieran hijos?, ¿permanecerían sin casarse por ellos? Por tanto (לָהֵן), sus nueras no debían sufrir por su causa. La partícula puede ser hebrea o un préstamo del arameo, lo que muestra la fluidez lingüística de los textos tardíos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3861', 'spa', 'Conjunción aramea: excepto, sino, sin embargo; ocasionalmente inferencial ''por tanto''.', 'Conjunción aramea presente exclusivamente en Daniel y Esdras, que funciona como bisagra lógica en decretos reales y argumentación teológica. Su fuerza principal es restrictiva — ''excepto'' o ''a menos que'' — como cuando los caldeos protestan que ''nadie puede revelar el asunto del rey excepto los dioses'' (Dn 2:11). También sirve como adversativo ''sino'' o ''pero'' (Dn 2:30; Esd 5:12), y en Daniel 4:27 se extiende hacia un uso inferencial: ''por tanto''. El árabe lākin (''pero'') y el hebreo ki ʾim (''excepto'') son sus paralelos funcionales más cercanos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3863', 'spa', 'Ojalá, si tan solo; también condicional ''si'' para situaciones contrafácticas; raramente negativo o dubitativo.', 'Ojalá, si tan solo; también condicional ''si'' para situaciones contrafácticas; raramente negativo o dubitativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3864', 'spa', 'Libios, pueblo del norte de África al oeste de Egipto, aliados de Egipto y Cus', 'Los lubim o libios eran un pueblo que habitaba el norte de África al oeste de Egipto, mencionados frecuentemente junto a Put (Somalia/Punt) y Cus (Etiopía/Nubia) como aliados militares de Egipto. Crónicas registra fuerzas libias entre los vastos ejércitos que los faraones egipcios llevaron contra Judá. Nahúm incluye a Libia entre los aliados que no pudieron salvar a Tebas de la conquista. Probablemente son los mismos que los lehabim en la Tabla de las Naciones del Génesis, identificando un pueblo descendiente de Mizraim (Egipto).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3865', 'spa', 'Lud; pueblo semitico descendiente de Sem, y separadamente un pueblo norteafricano (Ludim) descendiente de Mizraim.', 'Nombre propio que designa a dos pueblos distintos en la Tabla de las Naciones. Primero, Lud aparece como hijo de Sem junto a Arfaxad y Aram (Gn 10:22 = 1 Cr 1:17), tradicionalmente identificado con Lidia en el oeste de Anatolia (asirio Luddu). Segundo, un Lud africano distinto surge como guerreros junto a Cus y Fut en los oraculos profeticos (Ez 27:10; 30:5; Is 66:19), famosos como arqueros habiles y mercenarios. Esta doble identidad crea un enigma persistente en la geografia biblica. La formula conjuntiva ''y Lud'' en espanol y otras lenguas lo vincula a su contexto genealogico o militar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3866', 'spa', 'Lud/Ludim: (1) Lidia en Asia Menor, hijo de Sem; (2) pueblo africano, hijo de Mizraim, posiblemente confundidos', 'Lud aparece como hijo de Sem (representando a Lidia en Asia Menor) y Ludim como hijo de Mizraim/Egipto (representando un pueblo africano), lo cual genera debate académico sobre si se trata del mismo pueblo o de grupos distintos. El Lud asiático figura en genealogías junto a Aram y Arfaxad, claramente los lidios de Anatolia. Sin embargo, los textos proféticos sitúan a Lud/Ludim en África junto a Put y Cus, sugiriendo un pueblo norteafricano. Algunos eruditos proponen confusión textual, sugiriendo que los ''Ludim'' de Jeremías deberían leerse como ''Lubim'' (libios), como hace la Septuaginta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3867a', 'spa', 'Unirse a, adherirse a (Nifal); acompañar, escoltar (Qal)', 'El verbo לָוָה expresa la acción de vincularse a otra persona o grupo. En su forma Nifal (reflexivo-pasiva), que abarca casi todas las apariciones, describe el acto de unirse o adherirse: el nombre de Leví se explica por la esperanza de Lea de que su esposo ahora ''se uniría'' a ella (Gn 29:34), y los extranjeros ''se unen'' al SEÑOR (Isa 56:3, 6). El propio nombre Leví probablemente deriva de esta raíz. Una única aparición en Qal en Eclesiastés 8:15 usa el verbo transitivamente con el sentido de ''acompañar'': la alegría acompañará a la persona a lo largo de sus trabajos en la vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3867b', 'spa', 'Prestar o tomar prestado; en el Hifil, conceder un préstamo a alguien; en el Qal, recibir un préstamo de otro.', 'Prestar o tomar prestado; en el Hifil, conceder un préstamo a alguien; en el Qal, recibir un préstamo de otro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3868', 'spa', 'Apartarse, desviarse; figuradamente, ser torcido, perverso o engañoso en sus caminos.', 'Verbo poético que se encuentra casi exclusivamente en la literatura sapiencial, con dos significados relacionados: literalmente «apartarse o desviarse» y figuradamente «ser torcido o perverso». El participio Nifal naloz funciona casi como adjetivo con el significado de «perverso» o «torcido», aplicado a personas cuyos caminos son tortuosos (Pr 2:15), a quien desprecia a Jehová (Pr 3:32; 14:2) y a una conducta desviada (Is 30:12). Las formas Qal e Hifil en Proverbios 3:21 y 4:21 conservan el sentido literal: «no se aparten de tus ojos». El español perverso y el francés se détourner captan las dimensiones moral y espacial respectivamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3870', 'spa', 'Luz; antigua ciudad cananea renombrada Betel tras la visión de Jacob, y una segunda ciudad fundada por un exiliado hitita.', 'Topónimo que identifica la ciudad cananea donde Jacob durmió y soñó con la escalera celestial, rebautizándola después como Betel, ''casa de Dios'' (Gn 28:19; 35:6; 48:3). El nombre Luz aparece en las descripciones de los límites tribales de Efraín y Benjamín (Jos 16:2; 18:13) y en el relato de un hombre de la Luz original que edificó una nueva ciudad con el mismo nombre en territorio hitita (Jue 1:26). La Septuaginta lo traduce como Louza. El español transliterá simplemente como Luz, forma transparente que se conserva igual en francés y alemán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3871', 'spa', 'Tabla (esp. las tablas de piedra del pacto) o tablón/plancha usados en construcción y navegación', 'Tabla (esp. las tablas de piedra del pacto) o tablón/plancha usados en construcción y navegación');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3872', 'spa', 'Luhit, ciudad de Moab conocida por su cuesta empinada', 'Asentamiento moabita mencionado en oráculos contra Moab, conocido por «la subida de Luhit», probablemente un ascenso escarpado o paso de montaña. Tanto Isaías como Jeremías describen el llanto en esta cuesta mientras los fugitivos huyen de la destrucción, lo que sugiere que era una ruta clave de escape del territorio moabita, quizá hacia Edom. La repetición en ambos profetas puede indicar una fórmula oracular tradicional o un rasgo geográfico bien conocido asociado con la vulnerabilidad de Moab.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3874', 'spa', 'envolver, cubrir estrechamente, velar', 'Verbo que significa envolver con fuerza o cubrir estrechamente, usado tanto en sentido literal como figurado. La espada de Goliat está envuelta en un paño para su resguardo. Elías se cubre el rostro con su manto al encontrarse con la presencia de Dios, gesto de reverencia y temor. Isaías lo emplea metafóricamente para referirse al velo de duelo o ceguera espiritual que cubre a las naciones. La raíz transmite la idea de una cobertura que oculta por completo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3876', 'spa', 'Lot — sobrino de Abraham que escogió la llanura de Sodoma, ancestro de Moab y Amón', 'Lot — sobrino de Abraham que escogió la llanura de Sodoma, ancestro de Moab y Amón');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3877', 'spa', 'Lotan — jefe de clan horita, hijo de Seir y ancestro de clanes edomitas', 'Lotan es el nombre propio de un jefe horita enumerado entre los hijos de Seir en las genealogías de Edom (Gn 36:20, 22, 29; 1 Cr 1:38-39). Se le identifica como padre de Hori y Hemam (o Homam en Crónicas) y se le designa alluf («jefe») de los horitas, los habitantes pre-edomitas de la región montañosa de Seir. Su hermana Timna fue concubina de Elifaz, hijo de Esaú, y madre de Amalec (Gn 36:22, 12). La Septuaginta transcribe el nombre como Λωταν, y todas las lenguas receptoras lo conservan sin variación, confirmando su carácter de nombre propio sin contenido semántico traducible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3878', 'spa', 'Leví — tercer hijo de Jacob y Lea; la tribu sacerdotal descendiente de él.', 'Leví — tercer hijo de Jacob y Lea; la tribu sacerdotal descendiente de él.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3879', 'spa', 'Levitas (plural arameo), descendientes de Leví dedicados al servicio del templo', 'Esta forma plural aramea designa a los levitas, la tribu descendiente de Leví que fue apartada para el servicio en el santuario de Israel. El término aparece en los documentos arameos de Esdras que describen la restauración del templo y el culto bajo autorización persa. Estos pasajes emparejan consistentemente ''los sacerdotes y los levitas'', manteniendo la distinción entre ambos grupos de ministros sagrados: los sacerdotes aarónicos que ofrecían sacrificios, y el clan levítico más amplio que asistía en el servicio del templo, la música y la enseñanza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3881', 'spa', 'Levita(s) — miembros de la tribu de Leví al servicio del culto de Israel, o el patriarca Leví mismo.', 'Un adjetivo gentilicio derivado del nombre Leví, usado casi exclusivamente para designar a la tribu separada para el servicio del tabernáculo y del templo. Con 286 apariciones, abarca la organización en el desierto bajo Moisés (Nm 3-4), la preocupación deuteronómica por los levitas sin herencia (Dt 12:12; 14:27), los elaborados registros del templo en Crónicas y las reformas postexílicas de Esdras-Nehemías. En tres casos excepcionales (Nm 26:58; 1 Cr 23:27; 27:17), la palabra no se refiere a la clase sino al patriarca Leví en persona. Toda tradición traductora importante conserva la identidad tribal-funcional: español ''levitas,'' francés ''Lévites,'' alemán ''Leviten.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3882', 'spa', 'Leviatán: gran criatura marina (cocodrilo, ballena); serpiente mítica del caos vencida por Dios; dragón escatológico.', 'Livyatán es una de las palabras más evocadoras de las Escrituras hebreas: una criatura en la frontera entre la historia natural y la mitología cósmica. En Job 40:25–41:26 parece un animal real, probablemente el cocodrilo, descrito con detalle asombroso: escamas acorazadas, aliento de fuego e invulnerabilidad. Salmo 104:26 lo sitúa en el mar como algo que Dios creó «para jugar en él», sugiriendo una ballena. Pero en Job 3:8, Salmo 74:14 e Isaías 27:1 adquiere dimensiones mitológicas y escatológicas: un dragón del caos aplastado por Dios en la creación (Sal 74:14) o una «serpiente tortuosa» que será destruida al final de los tiempos (Isa 27:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3884', 'spa', 'Si no, a menos que, de no ser que; conjunción contrafactual que introduce condiciones contrarias a los hechos.', 'Si no, a menos que, de no ser que; conjunción contrafactual que introduce condiciones contrarias a los hechos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3885a', 'spa', 'Verbo de hospitalidad nocturna: alojarse o pasar la noche; de cosas, permanecer hasta la mañana; en sentido figurado, morar o habitar en un lugar. Abr', 'Verbo de hospitalidad nocturna: alojarse o pasar la noche; de cosas, permanecer hasta la mañana; en sentido figurado, morar o habitar en un lugar. Abraham invita a pernoctar (Gn 24:23-25), el levita es instado a quedarse a dormir en Guibeá (Jue 19:6-9), y Jacob duerme en Bet-el camino a Harán (Gn 28:11). Más allá de personas, el verbo se extiende a cosas que no deben permanecer hasta la mañana: la grasa sacrificial (Éx 23:18), el salario del jornalero (Lv 19:13) o el cuerpo de un ejecutado (Dt 21:23). El español distingue bien los matices: ''pernoctar'' para el alojamiento literal y ''morar'' para la habitación más permanente que se encuentra en Salmos y Job.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3885b', 'spa', 'Murmurar, quejarse o refunfuñar (especialmente Israel contra Dios/Moisés); también pernoctar (raíz distinta). Esta raíz es casi exclusivamente el voca', 'Murmurar, quejarse o refunfuñar (especialmente Israel contra Dios/Moisés); también pernoctar (raíz distinta). Esta raíz es casi exclusivamente el vocabulario de la rebelión en el desierto. Cada vez que Israel murmura contra Moisés y Aarón en la Torá, el texto emplea לון en sus formas Nifal o Hifil (Éx 15:24; Nm 14:2). El Hifil causativo aparece en Números 14:36, donde los espías que trajeron el informe negativo hicieron murmurar a toda la congregación. Una única aparición en el Salmo 59:15 conserva lo que parece ser la raíz homónima distinta que significa pernoctar o pasar la noche, recordándonos que la lexicografía hebrea debe distinguir cuidadosamente raíces que comparten la misma forma consonántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3887', 'spa', 'Burlarse o mofarse con desprecio; también (Hifil) actuar como intérprete, mediador o enviado entre partes.', 'Burlarse o mofarse con desprecio; también (Hifil) actuar como intérprete, mediador o enviado entre partes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3888', 'spa', 'Amasar masa; trabajar harina y agua hasta formar una masa para hornear pan.', 'Verbo concreto y sencillo que significa amasar masa, presente en escenas domésticas de preparación de alimentos a lo largo de la Biblia hebrea. Sara amasa tortas para los tres visitantes en Mamré (Gn 18:6), la médium de Endor amasa pan para el exhausto Saúl (1 Sam 28:24) y Tamar amasa la masa ante Amnón (2 Sam 13:8). Los profetas lo emplean para denunciar la falsa adoración: las mujeres amasan masa para hacer tortas a la Reina del Cielo (Jer 7:18), y Oseas compara al Israel corrupto con un panadero que deja de remover «desde el amasado de la masa» (Os 7:4). Los cognados son notablemente estables en todas las lenguas semíticas: arameo, siríaco y etiópico conservan formas casi idénticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3892', 'spa', 'Húmedo, fresco, verde; describe lo que conserva su humedad natural y no se ha secado ni marchitado.', 'Adjetivo que describe el estado de lo húmedo, fresco o verde: la condición natural de las plantas vivas antes de secarse. Jacob pela varas frescas de álamo en la estratagema de la cría del ganado (Gn 30:37); el nazareo debe abstenerse incluso de uvas frescas (Nm 6:3); y los captores de Sansón lo atan con cuerdas de arco nuevas que no han sido secadas (Jue 16:7-8). Ezequiel emplea el contraste entre el árbol verde y el seco como parábola de juicio: «Encenderé un fuego que devorará todo árbol verde y todo árbol seco» (Ez 21:3; cf. 17:24). El español fresco y verde captan esta cualidad de frescura viva y no desecada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3895', 'spa', 'Mandíbula o quijada; la mejilla como parte del cuerpo; también el topónimo Lehi. Este término abarca tanto el hueso duro como la carne blanda de la pa', 'Mandíbula o quijada; la mejilla como parte del cuerpo; también el topónimo Lehi. Este término abarca tanto el hueso duro como la carne blanda de la parte inferior del rostro. Como ''quijada'', aparece memorablemente en el arma improvisada de Sansón — la quijada de un asno con la que derribó a mil filisteos (Jue 15:15-17). Como ''mejilla'', designa la parte del rostro que recibe una bofetada de insulto (1 R 22:24; Is 50:6) o que revela belleza (Cnt 1:10). El topónimo Ramat-Lehi (''Altura de la Quijada'') preserva la palabra como punto geográfico vinculado a la hazaña de Sansón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3896', 'spa', 'Lehi, lugar de las hazañas de Sansón en territorio de Judá', 'Localidad en las tierras bajas de la Sefela donde Sansón mató a mil filisteos con la quijada de un asno. El topónimo se vincula con el juego de palabras sobre לְחִי (quijada): Sansón nombró el sitio Ramat-lehi («Altura de la Quijada») tras su victoria. Allí también brotó milagrosamente un manantial llamado En-hacoré («Fuente del que Clama»). Su ubicación exacta se desconoce, pero se hallaba cerca del territorio filisteo en la zona fronteriza de Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3897', 'spa', 'Lamer o devorar lamiendo; usado de animales que consumen y de naciones humilladas que ''lamen el polvo''.', 'Verbo que significa lamer o devorar lamiendo, usado tanto en sentido literal del consumo animal como en una poderosa metáfora de humillación y sumisión. Balac teme que Israel «lamerá» la tierra circundante como un buey lame la hierba (Nm 22:4), y el sacrificio de Elías en el altar es dramáticamente validado cuando el fuego del cielo «lamió» el agua del foso (1 Re 18:38). La expresión «lamer el polvo» se convierte en un modismo profético de sumisión absoluta: las tribus del desierto se postrarán ante el rey mesiánico y sus enemigos lamerán el polvo (Sal 72:9), reyes y reinas se inclinarán con el rostro en tierra (Isa 49:23), y las naciones se arrastrarán como serpientes lamiendo el polvo (Miq 7:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3898a', 'spa', 'Pelear, guerrear, combatir; en Nifal el verbo estándar para el conflicto armado; en el raro Qal, un combatiente poético.', 'El verbo hebreo principal para el combate militar. Casi todas sus 171 ocurrencias aparecen en el tronco Nifal, la forma reflexivo-recíproca natural para el enfrentamiento mutuo en batalla: naciones pelean entre sí, ejércitos chocan, reyes hacen la guerra. El español distingue entre luchar y pelear, y el francés emplea combattre, apuntando todos al conflicto armado organizado más que a disputas personales. Un diminuto grupo de formas Qal sobrevive solo en los Salmos, donde el poeta clama a Dios que ''pelee contra los que pelean contra mí'' (Sal 35:1), un modismo arcaico e intensamente personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3898b', 'spa', 'Comer, consumir alimento; sinónimo poético raro de אָכַל usado casi exclusivamente en la literatura sapiencial y la poesía.', 'Verbo poético poco frecuente que significa «comer» o «consumir como alimento», funcionando como sinónimo elevado del mucho más común אָכַל. Casi todas las apariciones se encuentran en Proverbios, donde la Sabiduría invita a sus huéspedes a «comer de mi pan» (Pr 9:5) y los malvados «comen el pan de la maldad» (Pr 4:17). El salmista se niega a «comer de sus manjares» (Sal 141:4). En Deuteronomio 32:24, el participio pasivo describe a los «devorados por la pestilencia», una notable extensión figurada. Las traducciones al español e inglés lo vierten consistentemente con vocabulario alimentario (comer, eat), mientras que el francés a veces recurre a combattre, reflejando confusión con el homónimo לחם I «luchar».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3899', 'spa', 'Pan, el alimento horneado básico del antiguo Oriente Próximo; por extensión, comida o sustento en general.', 'Léjem es el pan cotidiano de la Biblia hebrea: hogazas literales de grano horneado, partidas y compartidas en cada mesa, desde la tienda de Abraham (Gn 18:5) hasta el pan de la Presencia en el tabernáculo. Pero su alcance semántico va más allá de la panadería: designa también la ''comida'' en general, como cuando Levítico 3:11 llama al sacrificio ''el alimento (léjem) de Dios.'' Es revelador que el cognado árabe laḥm signifique ''carne'' y no pan, lo que sugiere que la raíz apuntaba originalmente a cualquier alimento antes de que el hebreo la restringiera a productos de grano. En un pasaje poético (Jr 11:19), léjem funciona como metáfora: ''destruyamos el árbol con su fruto (léjem),'' donde el profeta mismo es el ''pan'' que sus enemigos quieren consumir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3904', 'spa', 'concubinas, esposas secundarias en harenes reales (arameo)', 'Término arameo para designar a las concubinas, que aparece exclusivamente en Daniel 5, en el contexto del banquete sacrílego de Belsasar. El rey ordena traer los vasos sagrados del templo para que él, sus nobles, sus esposas y sus concubinas beban de ellos, en un acto deliberado de profanación. La presencia de las concubinas subraya el carácter libertino del festín. El vocablo refleja las prácticas poligámicas de la realeza neobabilónica y la memoria cultural del período persa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3905', 'spa', 'Apretar, presionar físicamente; oprimir o perseguir a personas social y políticamente; ser presionado o aplastado pasivamente. El verbo hebreo לחץ cap', 'Apretar, presionar físicamente; oprimir o perseguir a personas social y políticamente; ser presionado o aplastado pasivamente. El verbo hebreo לחץ captura tanto la presión física bruta como su metáfora sociopolítica. En sus escasos usos literales, describe a la burra de Balaam apretándose contra un muro (Nm 22:25) y a los amorreos acorralando a los danitas en la serranía (Jue 1:34). Pero de manera abrumadora, לחץ aparece como el vocabulario profético de la opresión sistemática — el clamor que llega a Dios en Éxodo 3:9, donde los capataces de Israel los ''oprimen'' bajo trabajos forzados. El verbo se concentra en pasajes de ley de alianza (Éx 22:21; 23:9) donde Dios ordena a Israel nunca oprimir al extranjero, precisamente porque saben lo que es la opresión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3906', 'spa', 'Opresión, angustia — presión aplastante ejercida por un poder hostil, especialmente la dominación extranjera', 'El sustantivo לַחַץ denota la presión aplastante de la opresión, típicamente infligida por una potencia extranjera o una autoridad despótica. Su peso teológico proviene del relato del Éxodo: Dios declara ''he visto también la opresión con que los egipcios los oprimen'' (Éx 3:9), e Israel debe recordar que el SEÑOR los libró de la opresión de Egipto (Dt 26:7). El ciclo de los jueces lo invoca repetidamente: cuando Israel clamaba bajo la presión de sus enemigos, Dios levantaba libertadores (Jue 2:18; 4:3; 6:9; 10:12). En 2 Reyes 13:4 se registra cómo la opresión de Hazael sobre Israel movió al rey a buscar el rostro del SEÑOR.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3907', 'spa', 'susurrar, murmurar encantamientos, encantar serpientes', 'Verbo que denota un habla silenciosa y furtiva, ya sea como cuchicheo conspirativo o como los conjuros murmurados por encantadores de serpientes. El salmista compara a sus enemigos con serpientes que no responden al susurro de los encantadores. Los siervos de David cuchichean entre sí cuando sospechan que el niño ha muerto. Otro salmo describe a adversarios que murmuran planes malintencionados. La raíz sugiere comunicación en voz baja y sigilosa, generalmente con connotaciones negativas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3908', 'spa', 'Susurro, encantamiento, hechizo; conjuro murmurado, amuleto u oracion susurrada, entre la magia y la devocion.', 'Sustantivo masculino que significa ''susurro'' o ''encantamiento'', abarcando un rango semantico sorprendentemente amplio, desde hechizos de encantadores de serpientes hasta oraciones susurradas. Jeremias 8:17 y Eclesiastes 10:11 lo usan para el encantamiento de serpientes — la formula murmurada que controla a las viboras venenosas. Isaias 3:3 lo aplica al ''experto en encantamientos'' entre los lideres de Jerusalen, mientras que Isaias 3:20 enumera לְחָשִׁים como amuletos o joyas-talismanes de las mujeres de Sion. Lo mas llamativo es que Isaias 26:16 lo emplea para una ''oracion susurrada'' derramada en la angustia. El espanol capta vividamente este abanico: ''encantamiento'' para la incantacion magica y ''susurro'' para la oracion musitada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3909', 'spa', 'Secreto, misterio: usado adverbialmente como ''en secreto, a escondidas''; de las ''artes secretas'' o encantamientos de los magos egipcios.', 'El sustantivo לָט (también escrito לַאַט) significa ''secreto'' o ''misterio'' y aparece solamente con la preposición בְּ en dos contextos marcadamente distintos. En tres pasajes narrativos funciona como adverbio con el sentido de ''en secreto, a escondidas'': Jael acercándose sigilosamente a Sísara para clavarle la estaca en la sien (Jue 4:21), Rut deslizándose sin ser vista hacia la era (Rut 3:7), y los siervos de Saúl hablando en secreto a David (1 Sam 18:22; 24:4). Pero en Éxodo, la misma raíz adquiere un matiz completamente diferente: el plural con sufijo, בְּלָטֵיהֶם, describe las ''artes secretas'' o ''encantamientos'' con los cuales los magos del faraón replicaron las señales de Moisés (Éx 7:22; 8:7, 18). Este contraste confirma una auténtica división semántica entre el sigilo humano y el misterio sobrenatural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3913', 'spa', 'Martillar, afilar, amolar; usado para la forja de metales, el afilado de hojas y figuradamente para miradas hostiles.', 'Un verbo que significa ''martillar'' o ''afilar'', arraigado en el acto físico de golpear metal. Génesis 4:22 presenta a Tubal-Caín como ''forjador de todo instrumento de bronce y hierro'', empleando el participio para describir al primer herrero del mundo. El sentido práctico de afilar hojas aparece en 1 Samuel 13:20, donde los israelitas debían acudir a los filisteos para afilar sus herramientas de labranza. El Salmo 7:12 advierte que Dios afila su espada contra los impíos. El uso figurado más vívido se halla en Job 16:9: el adversario ''aguza sus ojos contra mí'', una mirada penetrante y hostil que captura una intensidad amenazante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3914', 'spa', 'guirnaldas, decoraciones ornamentales talladas en los utensilios del templo', 'Diseños decorativos tallados en las bases de bronce de las fuentes del templo, posiblemente guirnaldas o patrones de festones. El término aparece únicamente en la descripción del mobiliario del templo de Salomón en 1 Reyes 7, junto con detalladas menciones de leones, bueyes, querubines y palmeras que adornan las bases móviles. Su forma exacta es incierta —algunas traducciones sugieren «espirales» o «festones»— pero el contexto indica claramente que se trata de relieves ornamentales que embellecían los vasos sagrados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3915', 'spa', 'Noche; el período oscuro desde el ocaso hasta el amanecer, opuesto al día; también la entidad cósmica ''Noche'' en la creación.', 'Una de las palabras más elementales del hebreo, לַיִל designa el período de oscuridad entre el ocaso y el amanecer. Aparece más de 230 veces, estructurando desde la temporalidad narrativa (''aquella noche,'' Gn 19:33) hasta las vigilias pactuales (Éx 12:42) y el lamento poético (Sal 6:7). En Génesis 1:5, Dios nombra la oscuridad ''Noche,'' elevándola de mera ausencia de luz a categoría cósmica con nombre propio. Su resonancia primordial de reposo, vulnerabilidad y encuentro divino se conserva en todas las lenguas: noche (español), nuit (francés), Nacht (alemán).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3916', 'spa', 'Noche; sustantivo arameo para el tiempo nocturno, usado en las visiones apocalípticas de Daniel recibidas ''de noche''.', 'El sustantivo arameo para ''noche'', cognado del hebreo לַיְלָה, que aparece exclusivamente en el libro de Daniel. Se presenta en estado enfático (לֵילְיָא), marcando siempre el escenario temporal de la revelación divina: el misterio es revelado a Daniel ''en visión de noche'' (Dn 2:19), Belsasar es muerto ''aquella misma noche'' (Dn 5:30), y las grandes bestias apocalípticas surgen del mar ''en mis visiones de la noche'' (Dn 7:2, 7, 13). Aunque ''noche'' es una palabra ordinaria, su emparejamiento constante con el lenguaje visionario en Daniel le confiere un peso extraordinario de revelación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3918', 'spa', 'león, término poético y arcaico para el rey de las bestias', 'Sinónimo poético y arcaico de león, menos frecuente que אַרְיֵה pero empleado en contextos literarios elevados. Job lo usa para describir al león poderoso que perece por falta de presa. Proverbios lo celebra como el más valiente entre las bestias, que no retrocede ante nada. Isaías lo empareja con el cachorro de león en un oráculo contra Egipto. El término aporta gravedad y colorido literario, procedente del vocabulario semítico compartido para este temible depredador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3919a', 'spa', 'Lais, nombre original de la ciudad norteña de Dan antes de que los danitas la conquistaran y renombraran', 'Lais era el nombre original de la ciudad más septentrional de Canaán antes de que la tribu de Dan la conquistara y la renombrara Dan. El libro de Jueces describe a Lais como una ciudad pacífica e incauta, habitada por sidonios que vivían con seguridad, hasta que los invasores danitas la destruyeron y la reconstruyeron como su centro tribal. El nombre Lais (que significa «león») aparece en paralelo con Lesem en el relato de Josué sobre la misma conquista, representando el asentamiento cananeo anterior a Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3920', 'spa', 'Capturar, tomar, asir — por conquista militar, por suerte, por trampa o por cohesión física; abarca apresamiento activo, captura pasiva, entrampamiento y congelación.', 'לָכַד es el verbo de la toma decisiva: el momento en que cae una ciudad, se apresa a un fugitivo o se cierra una trampa. Su Qal domina los relatos de conquista, donde Josué y los jueces ''capturan'' ciudad tras ciudad, mientras su Nifal emerge dramáticamente en el sorteo que expone a Acán (Jos 7:14-18), donde tribu, clan e individuo son progresivamente ''tomados'' hasta que el culpable queda al descubierto. El cognado árabe lakida (''pegarse, adherirse'') ilumina dos usos inusuales en Job donde el verbo describe agua congelándose y escamas trabándose entre sí: cohesión física en lugar de toma militar, un hilo semántico oculto para quien solo conoce las narrativas de conquista.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3923', 'spa', 'Laquis: una importante ciudad cananea fortificada, y posteriormente judía, en las tierras bajas de la Sefelá.', 'Laquis: una importante ciudad cananea fortificada, y posteriormente judía, en las tierras bajas de la Sefelá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3924', 'spa', 'Lazos — sujetadores textiles en las cortinas del tabernáculo que reciben los corchetes.', 'Lazos — sujetadores textiles en las cortinas del tabernáculo que reciben los corchetes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3925', 'spa', 'Verbo cuyo significado depende del sistema de raíces hebreas: en Qal significa ''aprender'' o ''acostumbrarse a''; en Piel, ''enseñar'' o ''adiestrar''. El ár', 'Verbo cuyo significado depende del sistema de raíces hebreas: en Qal significa ''aprender'' o ''acostumbrarse a''; en Piel, ''enseñar'' o ''adiestrar''. El árabe conserva el mismo contraste entre raíces: تَعَلَّمَ (forma V, medio-reflexiva) para aprender, frente a عَلَّمَ (forma II, causativa) para enseñar. El participio Piel (מְלַמֵּד) se convirtió en el término estándar para ''maestro'' en el hebreo tardío, y las formas pasivas describen a alguien disciplinado o adiestrado, como los guerreros ''entrenados para la guerra'' en 1 Crónicas 5:18 y Cantares 3:8.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3926', 'spa', 'Preposición poética equivalente a לְ (''a, para, sobre''), hallada exclusivamente en verso elevado (Job, Salmos, Isaías).', 'Una forma arcaica y ampliada de la preposición hebrea común לְ, empleada exclusivamente en registros poéticos y elevados. La forma completa לְמוֹ aparece en los discursos de Job (27:14; 29:21; 38:40; 40:4) y en poesía antigua como la bendición de Noé (Gn 9:26-27). Posee el mismo amplio alcance preposicional que לְ — dirección (''a''), beneficio (''para'') y referencia (''sobre'') — pero señala un tono solemne y elevado. El elemento מוֹ puede derivar de una partícula enclítica antigua, lo que confiere a la forma un sabor arcaizante propio de la poesía bíblica más temprana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3928', 'spa', 'Enseñado, instruido, acostumbrado; como sustantivo: discípulo, alumno. De la raíz לָמַד (''aprender/enseñar'').', 'Adjetivo derivado de la raíz לָמַד (''aprender, enseñar'') que describe a alguien que ha sido instruido o habituado. Isaías lo emplea como sustantivo para designar a los ''discípulos'': los seguidores del propio profeta (Is 8:16) y aquellos enseñados por el Señor (Is 50:4; 54:13), donde la ''lengua de los instruidos'' denota una elocuencia concedida por el Espíritu. Jeremías lo aplica de modo diferente: una asna salvaje ''acostumbrada'' al desierto (Jer 2:24) y un pueblo ''adiestrado'' en hacer el mal (Jer 13:23). Los contextos isaíanos apuntan al discipulado divino, mientras que los de Jeremías reflejan el matiz de hábito arraigado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3929', 'spa', 'Lamec (לֶמֶךְ) — nombre de dos figuras antediluvianas: el guerrero-poeta cainita y el descendiente de Set', 'El nombre Lamec (לֶמֶךְ) pertenece a dos figuras antediluvianas del Génesis. El Lamec cainita, séptimo desde Adán por la línea de Caín, es el primer polígamo registrado y el autor del feroz ''Canto de la Espada'' (Gn 4:23-24), en el que se jacta de una venganza desproporcionada. Sus hijos Jabal, Jubal y Tubal-Caín inauguran el pastoreo, la música y la metalurgia, lo que convierte a Lamec en figura bisagra entre el desarrollo de la civilización y la violencia. El Lamec setita, noveno desde Adán por la línea de Set, es el padre de Noé. Nombra a su hijo con un juego de palabras profético sobre ''consolar'' (נחם), esperando que Noé traiga alivio de la maldición sobre la tierra (Gn 5:28-31). El Cronista preserva únicamente la genealogía setita (1 Cr 1:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3932', 'spa', 'Burlarse, escarnecer, ridiculizar (Qal/Hifil); también balbucear o hablar de modo ininteligible (Nifal). Primordialmente un verbo de ridículo despecti', 'Burlarse, escarnecer, ridiculizar (Qal/Hifil); también balbucear o hablar de modo ininteligible (Nifal). Primordialmente un verbo de ridículo despectivo. Jerusalén se burla del ejército asirio derrotado (2 R 19:21), Dios se ríe de los malvados (Sal 2:4) y Proverbios advierte que burlarse del pobre insulta a su Creador (Pr 17:5). El verbo aparece en las formas Qal y Hifil con la misma fuerza básica. Un raro uso Nifal en Isaías 33:19 describe a un pueblo extranjero de habla ''balbuciente'' — lenguaje incomprensible percibido como farfulleo bárbaro. Este sentido fonético conecta con el cognado siríaco que significa ''tartamudear'', mostrando cómo la burla y el habla ininteligible comparten la idea de un lenguaje que no logra comunicar adecuadamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3933', 'spa', 'laag — burla, escarnio, mofa; ridículo despectivo dirigido contra personas o pueblos', 'El sustantivo masculino laag designa burla, escarnio o ridículo despectivo — aquel desprecio que hiere comunitariamente más que en privado. Aparece de manera prominente en los lamentos comunitarios de Israel: «Nos pusiste por escarnio de nuestros vecinos» (Sal 44:13; 79:4), y los peregrinos que ascienden claman: «Muy hastiada está nuestra alma del escarnio de los que están en holgura» (Sal 123:4). En Job 34:7, Elihú acusa a Job de «beber escarnio como agua», tratando la blasfemia como refrigerio casual. Ezequiel lo emplea en su alegoría de la copa de juicio de Jerusalén (Ez 23:32). La conexión del término con el habla tartamuda (Is 28:11) revela un hilo semántico interesante: la lengua extranjera e incomprensible era en sí misma una forma de mofa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3936', 'spa', 'Laadán — nombre propio de un ancestro efrateo de Josué y de un jefe de clan levita gersonita', 'Nombre propio masculino hebreo que aparece en Crónicas para dos individuos distintos. El primero es un efrateo incluido en la genealogía de la línea de Josué (1 Cr 7:26). El segundo es un levita gersonita que encabeza un clan principal responsable de la supervisión del tesoro del templo (1 Cr 23:7-9; 26:21). La LXX transcribe el nombre de diversas formas — Laadán, Edán, Ladán — lo cual refleja una incertidumbre temprana sobre su vocalización. Ambas figuras desempeñan un papel genealógico sin actividad narrativa directa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3939', 'spa', 'Ajenjo; planta amarga (Artemisia) usada figuradamente para la amargura del juicio divino, la injusticia y las consecuencias del pecado.', 'Sustantivo femenino que designa el ajenjo (Artemisia absinthium), empleado exclusivamente en contextos figurados a lo largo de la Biblia hebrea para evocar una amargura intensa. Amós lo empareja con rosh (''veneno'') para condenar la perversión de la justicia (Am 5:7; 6:12), mientras que Deuteronomio advierte que la idolatría produce ''una raíz que brota ajenjo'' (Dt 29:18). En Jeremías y Lamentaciones, Dios alimenta al pueblo infiel con ajenjo y agua amarga como castigo (Jer 9:15; 23:15; Lm 3:15, 19). Proverbios advierte que el final de la mujer seductora es ''amargo como el ajenjo'' (Pr 5:4). El cognado árabe laʿn significa ''maldición'', lo que sugiere la asociación del término con la aflicción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3940', 'spa', 'Antorcha, tea; un tizón encendido usado para iluminación, guerra, o como imagen visionaria y metafórica del fuego.', 'Antorcha, tea; un tizón encendido usado para iluminación, guerra, o como imagen visionaria y metafórica del fuego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3943', 'spa', 'torcer, agarrar con movimiento giratorio, girar bruscamente', 'Verbo que describe un movimiento de torsión, giro o agarre enérgico. Sansón agarró las dos columnas centrales, probablemente con una presa firme y retorcida. Booz se volvió de repente en la noche, sobresaltado al encontrar a Rut a sus pies. Job lo emplea metafóricamente para los cauces que «se desvían» o «se tuercen» cuando su agua se agota. La raíz transmite un movimiento rotacional súbito, ya sea para asir físicamente o para un cambio brusco de dirección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3944', 'spa', 'escarnio, burla despectiva; actitud y discurso de mofa dirigidos contra otros', 'Este sustantivo designa el acto o la actitud de escarnecer y burlarse de los demás. En Proverbios aparece en la expresión ''hombres de escarnio'' (burladores), refiriéndose a quienes habitualmente se mofan de la sabiduría y la justicia. Isaías lo emplea de manera similar para caracterizar a los gobernantes burladores de Jerusalén. La palabra subraya la actitud despectiva y el habla despreciativa de aquellos que rechazan la instrucción divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3947', 'spa', 'Tomar, asir, agarrar; recibir, aceptar; traer, ir a buscar; quitar; (Nifal) ser tomado; (Hitpael) relampaguear, flamear.', 'לָקַח es el verbo fundamental del hebreo bíblico para ''tomar'', usado casi mil veces en todo registro, desde lo cotidiano hasta lo trascendental. Dios toma la costilla de Adán (Gn 2:21), Abraham toma a Isaac (Gn 22:6), y los oficiales de Faraón toman a Sara (Gn 12:15). Pero el verbo no es monolítico: el contexto lo desplaza desde la aprehensión activa hasta la recepción voluntaria, desde ir a buscar y traer hasta que algo sea quitado. El Nifal proporciona la voz pasiva (''fue tomada'', Gn 2:23), y un raro Hitpael produce la vívida imagen de la espada flamígera ''centelleando de un lado a otro'' a la puerta del Edén (Gn 3:24). El árabe cognado narrowó hacia la concepción, mientras el etiópico se asentó en ''recibir'' — cada uno preservando una faceta de esta raíz ricamente polisémica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3948', 'spa', 'Enseñanza, instrucción o aprendizaje recibido; también poder persuasivo o seductor del discurso.', 'Derivado de la raíz laqach (''tomar, recibir''), este sustantivo concibe el conocimiento como algo que se recibe e interioriza. Moisés compara su enseñanza con la lluvia que empapa la tierra (Dt 32:2), y Proverbios elogia repetidamente al sabio que ''aumenta en doctrina'' (Pr 1:5; 9:9). El término puede designar tanto la adquisición subjetiva de conocimiento (lo que el alumno obtiene) como el contenido objetivo transmitido (lo que el maestro entrega, como en Pr 4:2). Un sentido secundario notable aparece en Proverbios 7:21, donde la seductora vence a su víctima con su leqach — no instrucción, sino el peligroso poder persuasivo de un discurso cautivador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3950', 'spa', 'Recoger, espigar o juntar; abarca la recolección de maná, el espigueo de grano sobrante y la reunión de personas', 'Recoger, espigar o juntar; abarca la recolección de maná, el espigueo de grano sobrante y la reunión de personas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3952', 'spa', 'Lamer o lengüetear — beber agua lamiéndola con la lengua (como perros o los soldados de Gedeón), o lamer una superficie (sangre, polvo)', 'Verbo físico vívido que capta la acción de la lengua contra un líquido o una superficie. En la célebre prueba de los guerreros de Gedeón (Jue 7:5-7), Dios selecciona al ejército según quién «lame el agua con su lengua como lame el perro» frente a quién se arrodilla: solo los trescientos que lamen son escogidos. El otro grupo de usos involucra a perros lamiendo sangre de superficies: la sombría profecía de Elías de que los perros lamerían la sangre de Acab (1 R 21:19), cumplida junto al estanque de Samaria (1 R 22:38). El español distingue bien ambos matices: «lame» para el contexto de beber agua, y «lamieron/lamerán» para las escenas de lamer sangre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3956', 'spa', 'Lengua; el órgano físico del habla, y por extensión idioma, una bahía en forma de lengua o una barra/lingote de oro.', 'En su sentido más básico, לָשׁוֹן designa la lengua física en la boca, pero el hebreo despliega esta palabra a lo largo de un campo semántico notable. La lengua es instrumento de bendición y maldición, de elocuencia y engaño (Sal 34:13, Job 5:21). Por metonimia natural pasa a significar un idioma completo, como cuando Génesis 10 cataloga las naciones ''conforme a sus lenguas.'' La misma metáfora de forma se extiende a la geografía — una bahía en forma de lengua del mar Muerto (Jos 15:2) — e incluso a objetos, como la célebre ''lengua de oro'' que Acán codició en Jericó (Jos 7:21). Los cognados árabe lisān y arameo liššān conservan el mismo sentido primario en todo el ámbito semítico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3957', 'spa', 'El sustantivo femenino lishkah (''cámara, sala, aposento'') designa un recinto o conjunto de recintos adosados a un edificio público o sagrado mayor, ut', 'El sustantivo femenino lishkah (''cámara, sala, aposento'') designa un recinto o conjunto de recintos adosados a un edificio público o sagrado mayor, utilizados para comer, almacenar, oficiar deberes sacerdotales o reunirse. Sus 48 apariciones se agrupan en tres contextos principales. Primero, en Samuel denota la sala donde se celebra una comida sacrificial (1 S 9:22). Segundo, en Jeremías se refiere a las cámaras del templo donde se ofrece vino a los recabitas (Jer 35:2, 4) y donde Baruc lee el rollo (Jer 36:10, 12, 20-21). Tercero, y con mayor frecuencia, en la visión del templo de Ezequiel (Ez 40-46) y en Esdras-Nehemías y Crónicas, lishkah designa las múltiples cámaras del complejo del templo usadas para habitación sacerdotal, almacenes levíticos y funciones de tesorería.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3960', 'spa', 'calumniar, usar la lengua maliciosamente contra otra persona', 'Esta forma verbal significa específicamente usar la lengua para calumniar, es decir, difundir falsedades malintencionadas acerca de otra persona. El participio Poʿel en el Salmo 101:5 describe a quien calumnia en secreto a su prójimo, conducta que el salmista declara intolerable. La forma Hifil aparece en Proverbios 30:10 como advertencia de no calumniar a un siervo ante su amo. El verbo capta el uso destructivo de la palabra para dañar la reputación ajena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3961', 'spa', 'Sustantivo arameo que significa lengua o idioma, usado en Daniel para designar grupos lingueisticos entre las naciones', 'Sustantivo arameo cognado del hebreo lashon, empleado exclusivamente en el libro de Daniel dentro de la formula recurrente ''pueblos, naciones y lenguas''. No se refiere al organo fisico, sino que designa de manera consistente un idioma hablado o la comunidad linguistica que lo habla. La repetida combinacion con ''pueblos'' y ''naciones'' subraya la universalidad de los decretos de Nabucodonosor y, mas adelante, de Dario. Tanto el espanol ''lengua'' como el ingles ''language'' capturan la extension metaforica del organo fisico al idioma hablado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3966', 'spa', 'Muy, sumamente, en gran manera — el intensificador hebreo primario de grado o magnitud.', 'מְאֹד es el intensificador más versátil del hebreo bíblico: aparece 301 veces amplificando adjetivos, verbos e incluso otros adverbios. Su primera ocurrencia marca la pauta: ''Vio Dios todo lo que había hecho, y he aquí que era muy bueno'' (Gn 1:31). Más allá de su uso adverbial, posee una rara acepción nominal de ''fuerza'' o ''capacidad'' en el Shemá: ''con todo tu מְאֹד'' (Dt 6:5), un pasaje tan llamativo que los traductores luchan por expresarlo (muy, mucho en español; très en francés; sehr en alemán). Esta doble capacidad — intensificador abstracto y sustantivo concreto — lo convierte en una de las palabras pequeñas de mayor peso teológico en hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3967', 'spa', 'Cien; numeral cardinal para 100 (singular, dual, plural); también unidad militar/administrativa; raramente una centésima parte.', 'El numeral hebreo básico para ''cien,'' מֵאָה aparece en formas singular, dual (מָאתַיִם, ''doscientos'') y plural (מֵאוֹת, ''cientos'') a lo largo del Antiguo Testamento. Sirve para contar edades en las genealogías del Génesis, medir las dimensiones del templo y registrar ejércitos y tributos. Los cognados abarcan toda la familia semítica — arameo מְאָה, árabe مِئَة, etíope ምእት — todos conservando la misma raíz. Más allá del conteo puro, la forma plural ''cientos'' se convirtió en designación estándar de compañías militares (Éx 18:21), y un pasaje (Neh 5:11) la emplea como fracción: ''la centésima parte.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3969', 'spa', 'Cien; numeral cardinal arameo para ciento, usado en cifras compuestas para contar personas, animales y bienes.', 'Sustantivo femenino arameo que significa ''cien'', presente en Esdras y Daniel tanto en forma absoluta como dual. En la dedicación del templo, los exiliados retornados ofrecieron cien toros, doscientos carneros y cuatrocientos corderos (Esd 6:17), mientras que Artajerjes autorizó hasta cien talentos de plata y cien coros de trigo (Esd 7:22). La forma dual matayim (''doscientos'') aparece junto a la forma absoluta. En español se emplea tanto ''cien'' como ''ciento'' según la posición sintáctica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3971b', 'spa', 'Defecto, mancha, imperfección física — especialmente en las regulaciones sacerdotales y sacrificiales. Un sustantivo que denota un defecto, mancha o i', 'Defecto, mancha, imperfección física — especialmente en las regulaciones sacerdotales y sacrificiales. Un sustantivo que denota un defecto, mancha o imperfección física. Aparece de manera predominante en la legislación levítica, donde descalifica a los sacerdotes del servicio en el templo (Lv 21:17-23) y hace que los animales sean no aptos para el sacrificio (Lv 22:20-25; Dt 15:21; 17:1). Fuera del ámbito cultual, la palabra describe la belleza impecable de Absalón (2 S 14:25) y del amado en Cantares 4:7. Se extiende figuradamente al defecto moral en Deuteronomio 32:5 y Job 11:15.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3972', 'spa', 'Algo, alguna cosa — pronombre indefinido, típicamente en contextos negativos con el sentido de ''nada en absoluto''', 'Algo, alguna cosa — pronombre indefinido, típicamente en contextos negativos con el sentido de ''nada en absoluto''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3974', 'spa', 'Luminaria, luz, portador de luz — una fuente de iluminación, ya sea cuerpo celeste, lámpara sagrada o resplandor figurado. El sustantivo מָאוֹר design', 'Luminaria, luz, portador de luz — una fuente de iluminación, ya sea cuerpo celeste, lámpara sagrada o resplandor figurado. El sustantivo מָאוֹר designa una fuente o portador de luz, desde las grandes luminarias del relato de la creación hasta las lámparas sagradas del tabernáculo. En Génesis 1:14-16 Dios crea los מְאֹרֹת — sol, luna y estrellas — para gobernar el día y la noche. La misma palabra describe la luz del candelabro de oro en Éxodo y Levítico, y se extiende figuradamente a ''la luz de los ojos'' que alegra el corazón (Pr 15:30) y ''la luz del rostro de Dios'' que expone el pecado oculto (Sal 90:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3976', 'spa', 'Balanzas, balanza — sustantivo en forma dual para el instrumento de pesaje usado literalmente en el comercio y figuradamente para el juicio divino.', 'Balanzas, balanza — sustantivo en forma dual para el instrumento de pesaje usado literalmente en el comercio y figuradamente para el juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3978', 'spa', 'Comida, alimento: sustancia comestible o provisión para comer, incluyendo frutos, grano y comidas preparadas.', 'Comida, alimento: sustancia comestible o provisión para comer, incluyendo frutos, grano y comidas preparadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3979', 'spa', 'cuchillo, instrumento cortante (para sacrificio o descuartizamiento)', 'Este sustantivo designa un cuchillo o instrumento cortante, y aparece en contextos de sacrificio y desmembramiento violento. Abraham tomó «el cuchillo» para inmolar a Isaac en la Akedá, momento culminante de su fe. El levita que halló muerta a su concubina tomó «un cuchillo» para dividir su cuerpo en doce partes, enviándolas por todo Israel como un llamado horroroso a la justicia. Proverbios advierte sobre los malvados cuyos dientes son como «cuchillos» que devoran al pobre. El término enfatiza la función cortante del instrumento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3982', 'spa', 'palabra, mandato, decreto real (hebreo tardío)', 'Sustantivo del hebreo tardío que aparece exclusivamente en Ester, designando una palabra, mandato o decreto real. El término refleja el contexto de la corte persa del libro, donde la palabra del rey tenía autoridad absoluta. Aparece en relación con la desobediencia de Vasti al mandato real (1:15), la obediencia de Ester a las instrucciones de Mardoqueo (2:20) y el decreto escrito de Ester sobre Purim (9:32). El sustantivo enfatiza la naturaleza autoritativa de los pronunciamientos reales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3984', 'spa', 'Sustantivo arameo que significa vaso o utensilio, referido a los implementos sagrados del templo de Jerusalen', 'Sustantivo arameo para vasos o utensilios, atestiguado unicamente en Esdras y Daniel, donde siempre se refiere a los vasos sagrados del templo llevados a Babilonia por Nabucodonosor. Estos implementos de oro y plata constituyen un hilo narrativo central: su confiscacion (Dan 5:2-3, 23), su inventario bajo el decreto de Ciro (Esd 5:14-15; 6:5) y su devolucion autorizada (Esd 7:19). El termino es cognado de formas sirias y del arameo antiguo, y tiene paralelo con el hebreo biblico keli.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3985', 'spa', 'Rehusar, negarse — verbo Piel que expresa rechazo deliberado o obstinada renuencia a obedecer', 'Rehusar, negarse — verbo Piel que expresa rechazo deliberado o obstinada renuencia a obedecer');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3986', 'spa', 'que rehúsa, el que se niega (siempre referido a desobedecer a YHWH, seguido de infinitivo)', 'Este participio adjetival describe a alguien que rehúsa o desobedece, y aparece exclusivamente en contextos de negarse a obedecer el mandato de Yahvé. El término funciona casi como una designación técnica para la desobediencia al pacto: Faraón repetidamente «rehúsa» dejar ir a Israel a pesar de plaga tras plaga, y Sedequías «rehúsa» rendirse ante Babilonia a pesar de las advertencias proféticas de Jeremías. La palabra siempre lleva un infinitivo que especifica la acción rechazada, subrayando la naturaleza deliberada de la desobediencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3988a', 'spa', 'El verbo מָאַס es una de las palabras más incisivas del vocabulario profético hebreo: el acto deliberado de apartarse de lo que debería haber sido val', 'El verbo מָאַס es una de las palabras más incisivas del vocabulario profético hebreo: el acto deliberado de apartarse de lo que debería haber sido valorado. Israel ''rechazó'' al SEÑOR como rey (1 S 8:7), Saúl fue ''desechado'' del reino (1 S 15:23, 26), y los edificadores ''desecharon'' la piedra que vino a ser cabeza del ángulo (Sal 118:22). El español distingue bien los matices: ''rechazar'' y ''desechar'' para el rechazo activo, ''despreciar'' y ''desdeñar'' para el desdén. El Nifal pasivo — ''ser rechazado'' — aparece en tres contextos conmovedores, incluyendo la esposa ''repudiada'' en Isaías 54:6 y la ''plata desechada'' de Jeremías 6:30. Un uso solitario en Job 7:16 lleva la palabra hacia la repulsión visceral: ''Aborrezco mi vida'', donde el rechazo se vuelve hacia uno mismo y se convierte en aborrecimiento existencial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3992', 'spa', 'punzante, doloroso (de espinas); maligno (de lepra)', 'Este participio hifil describe algo que punza o causa dolor, ya sean espinas literales que pinchan o una lepra maligna que se extiende de forma destructiva. Ezequiel lo emplea para referirse a una «zarza punzante» que ya no atormentará a Israel de entre las naciones hostiles que lo rodean. Los textos sacerdotales lo usan tres veces para hablar de «lepra maligna» en telas o edificios, designando la forma agresiva y propagante de la enfermedad que requería destrucción en vez de purificación. La raíz sugiere abrir o irritar, captando tanto el dolor agudo de las espinas como la expansión destructiva de la enfermedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3993', 'spa', 'Emboscada, celada; lugar de acecho o las tropas ocultas allí, usado en contextos militares y de asechanza.', 'Sustantivo masculino que significa ''emboscada'', derivado de la raíz אָרַב (''acechar, estar al acecho''), que designa tanto el lugar de ocultamiento como las tropas escondidas en él. Josué 8:9 lo emplea para la emboscada estratégica dispuesta contra Hai, mientras que Jueces 9:35 describe a los hombres de Abimelec saliendo de su emboscada contra Siquem. El Cronista lo usa dos veces en un solo versículo (2 Cr 13:13) para las tropas de Jeroboam posicionadas detrás del ejército de Judá, una doble celada que Dios tornó en derrota. El Salmo 10:8 lo extiende metafóricamente: el impío acecha ''en emboscada'' como león en la espesura, cazando al pobre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3994', 'spa', 'Maldición, imprecación; denuncia divina que acarrea ruina y privación como consecuencia del quebrantamiento del pacto.', 'Derivado de la raíz אָרַר (maldecir), este sustantivo designa una imprecación formal o maldición, especialmente una que porta autoridad divina. En Deuteronomio 28:20 Dios envía la מְאֵרָה sobre el desobediente, mientras que Malaquías 2:2 y 3:9 la invocan contra sacerdotes infieles y una nación que retiene sus ofrendas. Proverbios contrasta la maldición sobre la casa del impío (3:33) con las bendiciones sobre el generoso (28:27). En todas sus apariciones, el término apunta a consecuencias del pacto: no es una palabra casual de malicia, sino una denuncia solemne y vinculante con repercusiones materiales y espirituales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3996', 'spa', 'Entrada, umbral; puesta del sol (occidente); el acto de llegar o ingresar', 'Entrada, umbral; puesta del sol (occidente); el acto de llegar o ingresar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3999', 'spa', 'El Diluvio: la inundacion catastrofica en tiempos de Noe, el juicio de Dios mediante el agua sobre la tierra', 'El Diluvio: la inundacion catastrofica en tiempos de Noe, el juicio de Dios mediante el agua sobre la tierra');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4001', 'spa', 'pisoteo, aplastamiento violento; subyugación por la fuerza', 'Este sustantivo describe el pisoteo violento o la subyugación por la fuerza. Isaías lo emplea dos veces para caracterizar a una nación lejana como una ''de poder y de pisoteo'' (18:2, 7), posiblemente aludiendo a su agresión militar. La tercera aparición (22:5) se enmarca en un día de juicio descrito como ''día de tumulto, pisoteo y confusión''. El término evoca vívidamente la imagen de ser aplastado bajo los pies, ya sea por ejércitos invasores o por el juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4002', 'spa', 'manantial, fuente, nacimiento de agua', 'Sustantivo que designa manantiales o fuentes naturales de agua. En las profecías de restauración de Isaías, los manantiales aparecen como símbolo de la provisión divina para los exiliados que regresan por el desierto (35:7; 49:10). Eclesiastés emplea el término de forma metafórica en la enigmática descripción de la vejez y la muerte (12:6). La palabra resalta la cualidad vivificadora de los manantiales, particularmente significativa en los paisajes áridos del antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4005', 'spa', 'Lo mas selecto, lo mejor: la porcion mas escogida de un grupo, lo mas granado', 'Lo mas selecto, lo mejor: la porcion mas escogida de un grupo, lo mas granado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4007', 'spa', 'esperanza, expectativa; objeto de confianza o seguridad', 'Sustantivo que designa la esperanza o expectativa, y en particular el objeto concreto en el que se deposita la confianza. Isaías lo emplea dos veces para describir la esperanza frustrada de Judá en Egipto (Cus) como aliado contra Asiria (20:5-6), mostrando cómo las alianzas políticas resultaron decepcionantes. Zacarías lo aplica a la esperanza destruida de Filistea en Tiro como aliado (9:5). El término subraya no solo el sentimiento abstracto de esperanza, sino aquello concreto en lo que se espera, que en estos contextos demuestra ser poco fiable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4009', 'spa', 'Confianza, seguridad; aquello en lo que se confía; estado de protección o resguardo frente al peligro', 'Confianza, seguridad; aquello en lo que se confía; estado de protección o resguardo frente al peligro');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4013', 'spa', 'Fortaleza, plaza fuerte, lugar fortificado — estructura defensiva o ciudad amurallada construida para protección militar', 'Fortaleza, plaza fuerte, lugar fortificado — estructura defensiva o ciudad amurallada construida para protección militar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4017', 'spa', 'Mibsam (nombre propio: ''fragancia'' o ''aroma dulce'')', 'Nombre propio que significa ''fragancia'' o ''aroma dulce'', aplicado a dos individuos distintos en las Escrituras. El primer Mibsam fue un hijo de Ismael registrado en las genealogías (Génesis 25:13, 1 Crónicas 1:29). El segundo fue un descendiente de Simeón mencionado en Crónicas (1 Crónicas 4:25). Este nombre refleja la costumbre antigua de asignar nombres con asociaciones agradables, posiblemente como expresión de la alegría de los padres ante el nacimiento de un hijo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4021', 'spa', 'turbantes, gorros, tocados (cónicos o convexos, usados por los sacerdotes comunes, no por el sumo sacerdote)', 'Estos sustantivos femeninos plurales designan el tocado distintivo que usaban los sacerdotes ordinarios, a diferencia del turbante del sumo sacerdote. El término aparece exclusivamente en Éxodo y Levítico, describiendo las vestiduras sacerdotales que Aarón y sus hijos llevaban para ministrar en el santuario. Estos gorros o turbantes tenían aparentemente forma cónica o convexa, y formaban parte de las vestiduras sagradas que marcaban a los sacerdotes como santos para el Señor. Un pasaje los llama «gorros de lino para gloria y hermosura», destacando su papel en el simbolismo visual de la dignidad sacerdotal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4022', 'spa', 'Cosas exquisitas, dones preciados; lo más selecto del cielo y la tierra, usado para los dones naturales en bendiciones y poesía amorosa.', 'Sustantivo masculino que significa ''cosas selectas'' o ''dones preciados'', limitado a dos contextos poéticos notables: la bendición de Moisés sobre José (Dt 33:13-16) y las imágenes del jardín en el Cantar de los Cantares (4:13, 16; 7:14). En Deuteronomio, meged aparece cinco veces en rápida sucesión para enumerar los dones más selectos del cielo, del sol, de la luna, de los montes antiguos y de la plenitud de la tierra — una cascada de abundancia derramada sobre la porción de José. En el Cantar de los Cantares, describe los ''frutos exquisitos'' del jardín de la amada. El cognado árabe majd significa ''gloria, nobleza'', lo cual subraya el matiz de excelencia suprema.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4023', 'spa', 'Megido — ciudad estratégica fortificada en el valle de Jezreel que controlaba la ruta comercial de la Vía Maris', 'Megido (מְגִדּוֹ) fue una de las ciudades más estratégicamente importantes del antiguo Canaán, custodiando el paso a través de la cordillera del Carmelo hacia el valle de Jezreel a lo largo de la Vía Maris, ruta comercial y militar. Josué la enumera entre las ciudades cananeas conquistadas (Jos 12:21; 17:11), aunque Manasés no pudo expulsar por completo a sus habitantes (Jue 1:27). El cántico de Débora celebra la victoria «junto a las aguas de Megido» (Jue 5:19). Salomón la fortificó como una de sus ciudades de carros (1 Re 9:15), y el rey Josías encontró allí la muerte al enfrentar al faraón Necao (2 Re 23:29-30; 2 Cr 35:22). Zacarías 12:11 alude al «luto en la llanura de Megidón», y su resonancia apocalíptica pervive en el «Armagedón» (Har-Megido) de Apocalipsis.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4024b', 'spa', 'Migdol: ciudad-fortaleza fronteriza egipcia en el límite noreste, mencionada en el relato del Éxodo y en oráculos proféticos.', 'Nombre propio que designa a Migdol, una fortaleza fronteriza egipcia cuyo nombre deriva de la raíz semítica que significa ''torre'' (cf. מִגְדָּל). Aparece en dos contextos bíblicos distintos: el itinerario del Éxodo, donde Israel acampa ''delante de Migdol'' al salir de Egipto (Éx 14:2; Nm 33:7), y los oráculos de Jeremías dirigidos a la comunidad judía de la diáspora que vivía en ciudades egipcias ''en Migdol'' (Jer 44:1; 46:14). Ezequiel lo usa como marcador geográfico para toda la extensión de Egipto: ''desde Migdol hasta Sevene'' (Ez 29:10; 30:6). El nombre se transliteraConsistentemente en todas las lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4026', 'spa', 'El hebreo migdal evoca altura, fortaleza y visibilidad. Designa la ambiciosa torre de Babel (Gn 11:4-5), las torres defensivas que jalonaban las mural', 'El hebreo migdal evoca altura, fortaleza y visibilidad. Designa la ambiciosa torre de Babel (Gn 11:4-5), las torres defensivas que jalonaban las murallas de Judá (2 Cr 26:9-10), la torre del viñador en la parábola de Isaías (Is 5:2) y — con belleza — el cuello de la amada comparado con la torre de David cubierta de escudos (Cnt 4:4). Como elemento toponímico forma compuestos como Migdal-Eder, ''Torre del Rebaño'' (Mi 4:8). En un pasaje notable, Esdras lee la Torá desde un migdal de madera, una plataforma elevada (Neh 8:4), donde la metáfora arquitectónica pasa de la defensa militar a la instrucción pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4030', 'spa', 'objetos preciosos o selectos entregados como obsequios', 'Este término designa artículos de gran valor entregados como obsequios, frecuentemente en contextos de honor o tributo. La evidencia multilingüe subraya de forma constante la preciosidad y el alto costo de estos bienes. Aparece en relatos como la presentación de regalos por parte del siervo de Abraham a la familia de Rebeca (Génesis 24:53), los tesoros reales (2 Crónicas 21:3) y las ofrendas valiosas traídas a Ezequías (2 Crónicas 32:23). La palabra transmite tanto el valor material como la importancia social del acto de dar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4031', 'spa', 'Magog, nombre de un territorio y pueblo descendiente de Jafet', 'Magog aparece tanto como hijo de Jafet en la tabla genealógica de las naciones (Génesis 10:2, 1 Crónicas 1:5) como designación territorial en la profecía de Ezequiel contra Gog (Ezequiel 38:2, 39:6). Los intérpretes antiguos identificaron a Magog con los escitas o con regiones de Armenia y Capadocia. El nombre podría significar «tierra de Gog», vinculándolo con la figura profética que lidera fuerzas contra Israel en la visión escatológica de Ezequiel sobre el conflicto de los últimos tiempos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4032', 'spa', 'Terror, pavor; objeto de temor. Especialmente en la frase acuñada por Jeremías magor missabib, ''terror por todas partes''.', 'Derivado de la raíz gur III (''temer, tener pavor''), este sustantivo expresa un terror abrumador o aquello que lo causa. Es célebre sobre todo por la impactante frase de Jeremías magor missabib — ''terror por todas partes'' (Jer 6:25; 20:3, 10; 46:5; 49:29) —, que se convirtió casi en un sello profético. La misma frase resuena en el Salmo 31:13 y Lamentaciones 2:22, mostrando cuán profundamente esta acuñación de Jeremías penetró en el vocabulario israelita de la angustia. La palabra abarca desde el pavor abstracto hasta la causa concreta del espanto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4033', 'spa', 'Peregrinación o lugar de residencia temporal; estancia como extranjero en tierra ajena; también morada o habitación', 'Sustantivo derivado de la raíz גור (''peregrinar''), que abarca tanto el acto de vivir como forastero como el lugar donde se reside temporalmente. Las narraciones patriarcales lo emplean repetidamente para designar a Canaán como «la tierra de sus peregrinaciones» (Gn 17:8; 28:4; 36:7; 37:1), subrayando la condición de extranjería de Israel antes de su asentamiento. Jacob resume conmovedoramente sus «años de peregrinación» ante el faraón (Gn 47:9), y el salmista llama a los estatutos de Dios sus cánticos «en la casa de mi peregrinación» (Sal 119:54). En dos pasajes poéticos (Job 18:19; Sal 55:15), el término se desplaza hacia el sentido concreto de morada o habitación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4039', 'spa', 'Rollo, pergamino enrollado — un documento enrollado de pergamino o papiro usado para registrar profecía y ley. El término estándar para un rollo escri', 'Rollo, pergamino enrollado — un documento enrollado de pergamino o papiro usado para registrar profecía y ley. El término estándar para un rollo escrito en el hebreo bíblico tardío, que aparece casi exclusivamente en contextos proféticos. Su aparición más dramática está en Jeremías 36, donde Baruc escribe los oráculos de Jeremías en un rollo que el rey Joacim metódicamente corta y quema — solo para que el profeta dicte uno de reemplazo. Ezequiel recibe un rollo escrito por ambos lados con lamentaciones (Ez 2:9-3:3), y Zacarías ve un rollo volador de juicio (Zac 5:1-2). La referencia del salmista al ''rollo del libro'' (Sal 40:7) vincula el texto escrito con la obediencia al pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4042', 'spa', 'entregar, poner en manos de; conceder, otorgar', 'Verbo en forma Piel con dos sentidos relacionados: entregar a alguien en manos de un adversario, u otorgar algo como don o regalo. Génesis 14:20 celebra a Dios que entregó a los enemigos de Abraham en su mano. Proverbios 4:9 lo usa positivamente: la sabiduría otorgará una corona de honra. Oseas 11:8 contiene el clamor angustiado de Dios preguntando cómo puede entregar a Israel a la destrucción. El verbo capta el acto decisivo de transferir a alguien o algo de una parte a otra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4043', 'spa', 'Magen es la defensa personal del guerrero — un escudo pequeño y redondo que se llevaba al combate, distinto del tsinnah, más grande. Aparece en relato', 'Magen es la defensa personal del guerrero — un escudo pequeño y redondo que se llevaba al combate, distinto del tsinnah, más grande. Aparece en relatos bélicos desde el Cántico de Débora (''¿Se veía acaso escudo entre cuarenta mil?'' Jue 5:8) hasta los ejércitos apocalípticos de Ezequiel (38:4-5; 39:9). Pero su resonancia más perdurable es teológica: ''Yo soy tu escudo'' (Gn 15:1), la autodeclaración de Dios a Abraham, repetida a lo largo de los Salmos (Sal 3:3; 7:10; 18:2). Proverbios usa magen dos veces para referirse a un asaltante armado (6:11; 24:34), y Oseas 4:18 lo extiende a ''gobernantes'' — aquellos que escudan a la comunidad al gobernarla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4046', 'spa', 'Plaga, pestilencia o golpe devastador; epidemia enviada por Dios o matanza militar catastrófica', 'Plaga, pestilencia o golpe devastador; epidemia enviada por Dios o matanza militar catastrófica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4050', 'spa', 'sierra (herramienta para cortar piedra o madera)', 'Instrumento de corte utilizado principalmente para trabajar la piedra en contextos de construcción, como en la edificación del templo (1 Reyes 7:9). El término también aparece en el sombrío relato del trato de David hacia los amonitas cautivos, donde las sierras figuran entre herramientas de trabajo forzado o instrumentos de ejecución (2 Samuel 12:31, 1 Crónicas 20:3). Su etimología podría relacionarse con el sonido áspero y arrastrado que produce la herramienta al cortar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4054', 'spa', 'Tierra de pastoreo, ejido comunal que rodea una ciudad; específicamente los campos asignados a las ciudades levíticas.', 'מִגְרָשׁ designa el terreno abierto que rodea un asentamiento, reservado como tierra comunal — primordialmente para el pastoreo de ganado. La palabra aparece de forma abrumadora en las listas de asignación de ciudades levíticas de Josué 21 y 1 Crónicas 6, donde cada ciudad viene ''con sus campos de pastoreo.'' Números 35:2-5 establece el marco legal, prescribiendo límites medidos para estos ejidos. En la ciudad visionaria de Ezequiel (Ez 45:2, 48:15-17), el término se desplaza hacia ''espacio abierto'' en un sentido más arquitectónico. El español ejido — término jurídico para tierras comunales — ofrece un paralelo cultural notablemente preciso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4055', 'spa', 'Medida o porción asignada; vestidura o manto exterior; por extensión, un tapiz o alfombra extendida', 'Medida o porción asignada; vestidura o manto exterior; por extensión, un tapiz o alfombra extendida');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4057b', 'spa', 'Desierto, yermo; tierra abierta deshabitada usada para pastoreo o recorrida en travesías.', 'Con 270 apariciones, מִדְבָּר es el paisaje bíblico por excelencia de prueba, peregrinación y encuentro con Dios. Lejos de ser simplemente terreno árido, designa tierra abierta e inculta que podía servir de pasto (Jl 2:22; Sal 65:13) pero que en gran medida carecía de habitantes permanentes (Job 38:26). Es el escenario de los cuarenta años de Israel tras el Éxodo, el dominio de animales salvajes (Jr 2:24) y el lugar donde las voces proféticas claman (Is 40:3). La traducción uniforme en todas las lenguas como ''desierto'' o ''yermo'' (español desierto, francés désert, alemán Wüste) capta su sentido nuclear: tierra más allá de la habitación sedentaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4058', 'spa', 'Enraizado en un tronco semítico común compartido con el acadio madadu y el árabe madd (''extender''), este verbo significa fundamentalmente determinar e', 'Enraizado en un tronco semítico común compartido con el acadio madadu y el árabe madd (''extender''), este verbo significa fundamentalmente determinar el tamaño, la longitud o la cantidad usando una medida estándar. La visión del templo de Ezequiel concentra la mayor parte de sus apariciones, donde el guía angélico mide metódicamente cada puerta, muro y atrio. La forma Nifal (pasiva) aparece en contextos retóricos que afirman las bendiciones inconmensurables de Dios: la arena del mar ''no se puede medir'' (Os 1:10; Jer 33:22). Un único Hitpael en 1 Reyes 17:21 describe a Elías tendiéndose sobre el niño muerto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4060a', 'spa', 'Middah es el sustantivo principal de la Biblia hebrea para el acto y el resultado de medir. Aparece abrumadoramente en contextos técnicos arquitectóni', 'Middah es el sustantivo principal de la Biblia hebrea para el acto y el resultado de medir. Aparece abrumadoramente en contextos técnicos arquitectónicos y sacros: las cortinas del tabernáculo (Éxodo 26), la elaborada visión del templo de Ezequiel, y las asignaciones de reparación de la muralla en Nehemías. Sin embargo, la palabra se extiende más allá de la precisión de la cinta de medir hacia el terreno metafórico: Job 28:25 habla de Dios midiendo el peso del viento, y Jeremías 31:39 vislumbra un ''cordel de medir'' extendiéndose sobre la restauración de Jerusalén. Un caso fascinante es Salmo 133:2, donde la misma forma probablemente significa ''vestidura'' (del sustantivo homógrafo mad), recordándonos que la lexicografía hebrea siempre debe atender a las raíces homógrafas ocultas bajo esqueletos consonánticos idénticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4061', 'spa', 'tributo, impuesto recaudado sobre pueblos sometidos', 'Este préstamo del arameo designa pagos obligatorios impuestos a territorios conquistados o sometidos, y aparece exclusivamente en textos postexílicos relacionados con la administración persa. El término se encuentra en la correspondencia sobre la reconstrucción de Jerusalén, donde los opositores advierten al rey persa que la ciudad históricamente se negó a pagar tributo (Esdras 4:13, 20). Refleja las complejas realidades políticas del período de la restauración, cuando la comunidad judía debía cumplir con las obligaciones impuestas por el poder imperial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4066', 'spa', 'Contienda, discordia, riña; conflicto interpersonal provocado por la ira, el orgullo o un temperamento pendenciero', 'Contienda, discordia, riña; conflicto interpersonal provocado por la ira, el orgullo o un temperamento pendenciero');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4069', 'spa', 'Maddua es un adverbio interrogativo compuesto, probablemente contraído de mah-yadua (''¿qué siendo conocido?''), que significa ''¿por qué?'' o ''¿a causa d', 'Maddua es un adverbio interrogativo compuesto, probablemente contraído de mah-yadua (''¿qué siendo conocido?''), que significa ''¿por qué?'' o ''¿a causa de qué?'' Indaga no solo la causa sino el motivo — pregunta qué razonamiento subyace a una acción. En la narrativa, introduce preguntas directas de genuina indagación (Gn 26:27, ''¿Por qué habéis venido a mí?''; Éx 1:18, ''¿Por qué habéis dejado con vida a los niños?''). En la retórica profética se convierte en herramienta de reproche y lamento divino — Jeremías lo usa dieciséis veces, a menudo encabezando pares de preguntas retóricas que expresan la indignación perpleja de Dios ante la infidelidad de Israel (Jer 2:14, 31; 8:5, 19, 22). Isaías lo despliega en algunas de las confrontaciones más dramáticas de la Escritura: ''¿Por qué cuando vine, no había nadie?'' (Is 50:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4070a', 'spa', 'morada, lugar de habitación (arameo)', 'Sustantivo arameo que designa una morada o lugar de habitación, presente únicamente en Daniel. Las tres apariciones se refieren a la morada de Nabucodonosor durante su período de locura y humillación, cuando fue expulsado de la sociedad humana para vivir entre animales salvajes. El término subraya el cambio radical en las circunstancias del rey: del palacio al desierto, de una morada humana a habitar entre bestias. Daniel emplea este detalle para ilustrar tanto la soberanía divina como la posterior restauración del rey.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4074', 'spa', 'Maday / Media — un hijo de Jafet y la nación/territorio de los medos en el antiguo Cercano Oriente. Designa tanto a la figura ancestral en la Tabla de', 'Maday / Media — un hijo de Jafet y la nación/territorio de los medos en el antiguo Cercano Oriente. Designa tanto a la figura ancestral en la Tabla de las Naciones (Gn 10:2 = 1 Cr 1:5) como al poderoso pueblo iraní y territorio conocido como Media. Los medos aparecen primero como lugar del exilio israelita — las ''ciudades de los medos'' adonde Asiria deportó a los israelitas del norte (2 R 17:6; 18:11). Luego emergen como poder militar amenazante a quienes Isaías convoca contra Babilonia (Is 13:17; 21:2). Los textos monárquicos tardíos y postexílicos emparejan regularmente ''Media y Persia'' como imperio dual (Est 1:3, 14, 18, 19; 10:2; Dn 8:20), reflejando la confederación medo-persa histórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4076', 'spa', 'Madai: los medos y su territorio Media, el antiguo pueblo y reino iranio al este de Mesopotamia.', 'Madai (מָדַי) designa tanto a los medos como grupo étnico como a Media como territorio geográfico. En Daniel 5:28 el reino de Belsasar es entregado a los medos y persas, y las leyes de los medos figuran prominentemente en Daniel 6:8, 12, 15, subrayando la inmutabilidad del derecho medo-persa. Esdras 6:2 localiza el decreto de Ciro en la provincia de Media. En Génesis 10:2, Madai aparece como hijo de Jafet en la tabla de las naciones, estableciendo la identidad genealógica del pueblo. En español, ''Media'' refleja el sentido territorial, mientras que ''los medos'' preserva el gentilicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4079', 'spa', 'contienda, discordia, riña', 'Término para el conflicto interpersonal y la discordia, empleado casi exclusivamente en Proverbios para caracterizar conductas sociales destructivas. La literatura sapiencial advierte contra quienes siembran la contienda y destaca especialmente la imagen proverbial de «la mujer pendenciera» como símbolo de discordia doméstica (Proverbios 21:9, 27:15). La palabra aparece junto a otros términos afines al conflicto, configurando un retrato del daño social que causan las personas pendencieras que generan división en comunidades y familias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4080', 'spa', 'Un nombre profundamente entrelazado con la historia de Israel. Madián (מִדְיָן) designa al hijo de Abraham y Cetura (Gn 25:2), la tribu nómada árabe d', 'Un nombre profundamente entrelazado con la historia de Israel. Madián (מִדְיָן) designa al hijo de Abraham y Cetura (Gn 25:2), la tribu nómada árabe descendiente de él, y el territorio que habitaban al este del golfo de Aqaba. Moisés halló refugio en tierra de Madián (Éx 2:15), se casó con Séfora, hija de un sacerdote madianita (Éx 2:16; 3:1), y más tarde Israel se enfrentó violentamente con fuerzas madianitas en el desierto (Nm 31). La dramática derrota de Madián por Gedeón (Jue 7-8) se volvió proverbial — Isaías invoca ''el día de Madián'' (Is 9:3) como paradigma de la liberación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4082', 'spa', 'Provincia o distrito administrativo de un imperio, especialmente las divisiones territoriales de los reinos persa y babilónico.', 'Provincia o distrito administrativo de un imperio, especialmente las divisiones territoriales de los reinos persa y babilónico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4083', 'spa', 'Provincia, distrito — región administrativa bajo gobierno imperial, especialmente en contextos persas y babilónicos', 'El sustantivo מְדִינָה (medinah) designa una provincia administrativa o distrito jurisdiccional dentro de un imperio mayor. Aparece exclusivamente en literatura postexílica y exílica, reflejando las realidades políticas de la gobernanza babilónica y persa. En Esdras, nombra la provincia «de Más Allá del Río» (Esd 4:15; 5:8; 6:2; 7:16), la satrapía que abarcaba Judá y sus vecinos. Daniel lo emplea para la provincia de Babilonia, sobre la cual Daniel es nombrado jefe (Dn 2:48-49), y para la llanura de Dura dentro de esa provincia, donde Nabucodonosor erige su imagen de oro (Dn 3:1-3, 12, 30). El término conlleva un tono inherentemente burocrático: designa el territorio como objeto de administración, tributación y nombramiento real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4084', 'spa', 'Madianita, adjetivo o sustantivo gentilicio que designa a una persona o pueblo procedente de Madian', 'Adjetivo gentilicio formado a partir de Madian, usado tanto en singular como en plural para identificar a individuos o grupos de origen madianita. Aparece en momentos narrativos clave: los comerciantes madianitas que compran a Jose (Gn 37:28), el suegro de Moises, Hobab (Nm 10:29), la mujer madianita Cozbi cuya relacion con un israelita desencadena una plaga (Nm 25:6, 14-15), y el mandato divino de atacar a los madianitas (Nm 25:17; 31:2). La forma femenina midyanit identifica especificamente a Cozbi en la crisis de Baal-Peor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4090', 'spa', 'contienda, discordia, querella', 'Sustantivo que denota contienda, discordia y comportamiento pendenciero, presente principalmente en Proverbios. El libro lo emplea para advertir contra las personas conflictivas: el ''hombre de contiendas'' que aviva conflictos, y especialmente la ''mujer contenciosa'' mencionada repetidamente como alguien con quien resulta insoportable convivir. El término aparece a menudo emparejado con palabras afines para disputa y conflicto, subrayando la naturaleza destructiva de las riñas crónicas. Proverbios presenta la contienda como un fuego que solo necesita combustible para seguir ardiendo (26:20-21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4093', 'spa', 'Conocimiento, ciencia, saber (logro intelectual, a menudo emparejado con sabiduría); pensamiento, mente (conciencia interior).', 'El sustantivo masculino מַדָּע es una palabra del hebreo tardío para ''conocimiento'' o ''ciencia'', que aparece solo seis veces y se concentra en contextos de dotación intelectual excepcional. Cinco apariciones giran en torno a la sabiduría otorgada divinamente a Salomón (2 Cr 1:10-12) y la educación cortesana de Daniel en Babilonia (Dan 1:4, 17), donde מַדָּע aparece junto a חָכְמָה (''sabiduría'') y דַּעַת (''entendimiento'') como términos superpuestos pero distintos para la capacidad intelectual. La sexta aparición, en Eclesiastés 10:20, gira hacia lo interior: ''ni aun en tu pensamiento maldigas al rey'', donde significa ''pensamiento'' o ''mente'', el espacio privado de la conciencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4099', 'spa', 'Hamedata — padre de Amán el agagueo, nombre persa que posiblemente significa ''dado por la luna''', 'Hamedata es el padre de Amán, el principal antagonista del libro de Ester. El nombre aparece exclusivamente en la fórmula patronímica ''Amán hijo de Hamedata el agagueo'' (Est 3:1, 10; 8:5; 9:24), con una sola ocurrencia que omite el epíteto agagueo (9:10). BDB lo vincula al persa māh (''luna''), sugiriendo un significado teofórico. Las traducciones principales (eng Hammedatha, spa Hamedata, fra Hammedatha, deu Hammedata) lo transliteran con variaciones fonéticas mínimas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4100', 'spa', '¿Qué? ¿cómo? ¿por qué? ¿cuánto?; pronombre interrogativo y exclamativo para cosas, modo, grado, cantidad y causa.', 'El pronombre interrogativo מָה es la palabra hebrea polivalente para preguntas no personales — la contraparte de מִי (''¿quién?'') para personas. Mucho más que un simple ''¿qué?'', se flexiona a través de múltiples roles semánticos: pregunta por la identidad (''¿qué es esto?''), el modo (''¿cómo lo haremos?''), el grado (''¡cuán maravilloso!''), la cantidad (''¿cuántos días?''), el tiempo (''¿hasta cuándo?'') y la causa (''¿por qué?''). Su uso exclamativo en los Salmos (''¡cuán amables son tus moradas!'', Sal 84:1) revela una palabra igualmente cómoda en la interrogación urgente y en la alabanza admirada. Las múltiples formas de vocalización (מַה, מֶה, מַ) se adaptan a la fonología circundante sin alterar el significado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4101', 'spa', 'Pronombre y partícula interrogativa aramea: ¿qué?, lo que sea; ¡cómo! (modo/grado); ¿por qué? (razón)', 'Pronombre y partícula interrogativa aramea: ¿qué?, lo que sea; ¡cómo! (modo/grado); ¿por qué? (razón)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4102', 'spa', 'Demorarse, detenerse, tardar, vacilar — dicho de personas que hacen una pausa o esperan antes de actuar (solo Hitpalpel).', 'Este verbo aparece únicamente en su forma Hitpalpel (reflexivo intensivo), transmitiendo el sentido de demorarse, tardar o vacilar. La reduplicación de la raíz intensifica la idea de demora. En Génesis 19:16, Lot ''se demoraba'' mientras los ángeles le urgían a huir de Sodoma — un momento de vacilación potencialmente fatal. Éxodo 12:39 explica que Israel no pudo detenerse en Egipto, vinculando la urgencia con el pan sin levadura. Habacuc 2:3 promete que la visión profética no tardará, empleando el mismo verbo para el tiempo divino. El Salmo 119:60 declara ''no me demoré en guardar tus mandamientos'', asociando la palabra con la obediencia diligente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4103', 'spa', 'Confusión, tumulto, pánico — desorden aterrador, frecuentemente infligido por Dios, que dispersa ejércitos o perturba comunidades', 'El sustantivo מְהוּמָה (mehumah) denota un pánico repentino y desorientador o un tumulto caótico, frecuentemente atribuido a la intervención divina en batalla. Dios promete sembrar «confusión» entre los enemigos de Israel como arma de guerra santa (Dt 7:23; 28:20), y este patrón se repite a lo largo de la literatura narrativa: el SEÑOR envía pánico entre los filisteos en Mizpa (1 S 7:10), durante la incursión de Jonatán (1 S 14:20), entre los madianitas ante Gedeón (Jue 7:22, implícito) y entre las fuerzas de Senaquerib (2 Cr 15:5-6). Los profetas extienden la imagen a escenarios escatológicos donde las naciones se disuelven en confusión mutua (Zac 14:13; Ez 22:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4105', 'spa', 'Mehetabel (nombre propio: ''Dios beneficia'' o ''Dios hace el bien'')', 'Nombre propio que significa ''Dios beneficia'' o ''Dios hace el bien'', usado por dos personajes bíblicos. La primera fue una princesa edomita, hija de Matred y esposa del rey Hadar (Génesis 36:39, 1 Crónicas 1:50). El segundo fue el abuelo de Semaías, un falso profeta que intentó intimidar a Nehemías (Nehemías 6:10). El nombre mismo da testimonio de fe en la bondad divina, aunque irónicamente el descendiente del segundo portador se opuso a la obra restauradora de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4106', 'spa', 'rápido, hábil, diligente', 'Adjetivo que describe rapidez o destreza en la acción, ya sea en habilidad física, agudeza mental o determinación moral. Caracteriza al escriba hábil en su oficio (Salmo 45:2, Esdras 7:6), al trabajador diligente que sobresale en su labor (Proverbios 22:29) y al gobernante que actúa con prontitud para establecer justicia (Isaías 16:5). El término valora tanto la competencia como la presteza, sugiriendo que la verdadera destreza implica no solo capacidad sino ejecución oportuna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4109', 'spa', 'viaje, camino, trayecto', 'Término del hebreo tardío que describe la distancia recorrida o el paso a través del espacio. Mide la extensión de la arquitectura del templo en la visión de Ezequiel (Ezequiel 42:4), la duración del viaje anticipado de Nehemías desde Babilonia a Jerusalén (Nehemías 2:6) y el tamaño de Nínive como ''camino de tres días'' (Jonás 3:3-4). En Zacarías 3:7, la forma plural puede denotar ''libre acceso'' o ''derecho de paso'' por la corte celestial, pasando de lo espacial a lo social.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4111', 'spa', 'Mahalalel, nombre propio que significa ''alabanza de Dios'', llevado por un descendiente de Set y un hombre de Juda', 'Nombre propio masculino hebreo que significa ''alabanza de Dios'', compuesto por la raiz halal (''alabar'') y El (''Dios''). Se refiere principalmente al bisnieto de Set en la genealogia antediluviana de Genesis 5:12-17, cuya vida se registra en 895 anos. Un segundo Mahalalel aparece mucho despues como antepasado de la tribu de Juda en Nehemias 11:4. La construccion teoforica del nombre lo situa junto a otros nombres de alabanza en la Biblia hebrea, expresando la conviccion de que Dios es digno de toda aclamacion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4114', 'spa', 'Destrucción total, catástrofe; usado casi exclusivamente del juicio divino sobre Sodoma y Gomorra como advertencia paradigmática.', 'Sustantivo femenino que designa una destrucción total y catastrófica, evocado casi siempre en comparación con la aniquilación de Sodoma y Gomorra. La construcción «como la destrucción de Sodoma» se convirtió en una fórmula fija para expresar la forma más extrema del juicio divino (Deut 29:22; Isa 13:19; Jer 49:18; 50:40; Amós 4:11). En Isaías 1:7, la frase se aplica a la devastación causada por invasores extranjeros, mostrando la capacidad del término para describir cualquier aniquilación irreversible. Las glosas multilingües conservan la construcción comparativa, subrayando su carácter formulaico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4115', 'spa', 'cepo o instrumento de sujeción para castigo', 'Instrumento de reclusión que obligaba al cautivo a adoptar una postura forzada o retorcida, utilizado para castigar a Jeremías por su ministerio profético. Fue puesto en ''el cepo que estaba en la puerta superior de Benjamín en la casa del Señor'' (Jeremías 20:2-3), y el dispositivo se menciona de nuevo en Jeremías 29:26 como parte del aparato para sujetar a profetas considerados locos. El término también aparece en la persecución de Hanani el vidente por parte de Asa (2 Crónicas 16:10), lo que sugiere que era un instrumento habitual para silenciar voces disidentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4116a', 'spa', 'Apresurarse, darse prisa (Piel); ser precipitado o impetuoso (Nifal) — urgencia de acción frente a temeridad de carácter.', 'Apresurarse, darse prisa (Piel); ser precipitado o impetuoso (Nifal) — urgencia de acción frente a temeridad de carácter.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4118b', 'spa', 'Rápidamente, apresuradamente — un adverbio de premura que siempre modifica al verbo inmediatamente precedente. מַהֵר (II) funciona como adverbio que s', 'Rápidamente, apresuradamente — un adverbio de premura que siempre modifica al verbo inmediatamente precedente. מַהֵר (II) funciona como adverbio que significa ''rápidamente'' o ''apresuradamente'', derivado del infinitivo absoluto Piel de מהר (''apresurarse''). Sus 17 apariciones siempre siguen directamente al verbo que modifican, confiriendo urgencia a la acción descrita. La palabra aparece con mayor densidad en Deuteronomio, donde subraya tanto la rapidez del juicio divino — ''ciertamente pereceréis pronto de la tierra'' (Dt 4:26; 28:20) — como el ritmo de la guerra de Dios a favor de Israel: ''Él los destruirá rápidamente delante de ti'' (Dt 9:3). La narrativa del becerro de oro la usa dos veces: ''se han desviado rápidamente del camino que les mandé'' (Dt 9:12, 16; cf. Éx 32:8), transmitiendo la impactante velocidad de la apostasía de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4119', 'spa', 'Precio de novia, dote matrimonial pagada a la familia de la novia', 'Sustantivo que designa el precio de novia o dote que se pagaba a la familia de la prometida. Era el pago acostumbrado que un hombre entregaba al padre de una mujer para tomarla como esposa en la cultura del antiguo Cercano Oriente. Éxodo 22:16 alude a ''la dote de las vírgenes'' en la legislación sobre la seducción. Génesis 34:12 relata a Siquem ofreciendo pagar cualquier cantidad de dote por Dina. Saúl exigió a David un precio de novia peligroso por Mical (1 Samuel 18:25). El término refleja antiguas costumbres matrimoniales que implicaban transacciones económicas entre familias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4120', 'spa', 'Rápidamente, apresuradamente, con prisa — un adverbio que insta a una acción pronta o describe una ocurrencia veloz. Un sustantivo adverbial de la raí', 'Rápidamente, apresuradamente, con prisa — un adverbio que insta a una acción pronta o describe una ocurrencia veloz. Un sustantivo adverbial de la raíz מהר (''apresurarse'') usado a lo largo de la Biblia hebrea para expresar urgencia y velocidad. A menudo sigue al verbo para intensificar la rapidez de la acción — Aarón debe ir rápidamente a hacer expiación y detener la plaga (Nm 16:46), los gabaonitas suplican ''sube a nosotros rápidamente y sálvanos'' (Jos 10:6), y Husai advierte a David que cruce el Jordán rápidamente para no ser devorado (2 S 17:16). En textos poéticos precede al verbo para mayor énfasis: Isaías describe a Dios convocando a una nación lejana que viene velozmente (Is 5:26), y el salmista ora ''sé una roca de refugio para mí; apresúrate a librarme'' (Sal 31:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4121', 'spa', 'Maharai (nombre propio: posiblemente ''apresurado'' o ''impetuoso'')', 'Nombre propio de uno de los valientes guerreros de David. Maharai el netofatita sirvió como uno de los combatientes de élite en el ejército de David y posteriormente como comandante de una división de 24.000 hombres durante el décimo mes del año. Aparece tanto en la lista de los héroes de David (2 Samuel 23:28, 1 Crónicas 11:30) como en las divisiones administrativas bajo su reinado (1 Crónicas 27:13). El nombre posiblemente deriva de una raíz que significa ''apresurarse''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4124', 'spa', 'Moab — la nación, el pueblo y el territorio al este del mar Muerto, descendiente de Lot.', 'Moab nombra tanto a un pueblo como a su patria en la meseta elevada al este del mar Muerto. Génesis 19:37 remonta el origen de la nación a la hija mayor de Lot, y el nombre porta una etimología incómoda que el texto no elude. Moab figura prominentemente en la narrativa del desierto de Israel: las llanuras de Moab son el punto de partida para la entrada en Canaán (Nm 22-36; Dt 1:5). La relación oscila entre hostilidad (el intento de maldición de Balac, las guerras moabitas) y parentesco (Rut la moabita). El nombre pasa sin alteración a prácticamente todas las lenguas — español Moab, francés Moab, alemán Moab — reflejando su reconocimiento universal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4125', 'spa', 'Moabita: adjetivo y sustantivo gentilicio para designar a una persona originaria de Moab, aplicado tanto a hombres como a mujeres. Aparece en formas m', 'Moabita: adjetivo y sustantivo gentilicio para designar a una persona originaria de Moab, aplicado tanto a hombres como a mujeres. Aparece en formas masculinas y femeninas, singulares y plurales, funcionando como adjetivo y como sustantivo. El término adquiere especial relevancia en la historia de Rut, donde ''Rut la moabita'' (Rut 1:22; 2:2, 6, 21; 4:5, 10) es identificada con este calificativo nada menos que seis veces, una estrategia narrativa que mantiene visible su identidad extranjera incluso mientras es acogida en Israel. Deuteronomio 23:4 excluye al ''moabita'' de la asamblea del SEÑOR, creando una tensión teológica que el libro de Rut parece diseñado para explorar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4127', 'spa', 'Derretir, disolver o hacer que se derrita; usado para describir la tierra disolviéndose al toque de Dios y los corazones derritiéndose de miedo. Un ve', 'Derretir, disolver o hacer que se derrita; usado para describir la tierra disolviéndose al toque de Dios y los corazones derritiéndose de miedo. Un verbo vívido que retrata la disolución, ya sea el derretimiento físico o el colapso del valor humano. Cuando Dios toca la tierra, esta se derrite (Am 9:5); cuando su voz truena, la tierra se disuelve (Sal 46:6). Los habitantes de Canaán ''se derritieron'' ante Israel (Éx 15:15, Jos 2:9), y los corazones de los guerreros se disuelven como cera. En sus usos causativos, Dios ablanda la tierra empapada por la lluvia (Sal 65:10) o disuelve a una persona en el sufrimiento (Job 30:22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4131', 'spa', 'Tambalear, temblar, resbalar, ser movido; en Hifil, hacer caer o derribar', 'Tambalear, temblar, resbalar, ser movido; en Hifil, hacer caer o derribar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4132', 'spa', 'Pértiga o vara para transportar; tambaleo o resbalón (abstracto); travesaño de un yugo, figuradamente opresión.', 'Se usa concretamente para designar las pértigas o varas sobre las cuales se transportaban objetos pesados, como el enorme racimo de uvas traído de Escol entre dos hombres (Núm 13:23). En los Salmos adquiere un sentido abstracto de tambaleo o resbalón, siempre negado para afirmar la protección firme de Dios: no permitirá que el justo sea conmovido (Sal 55:23; 66:9; 121:3). En Nahúm 1:13 el término se estrecha al travesaño de un yugo, imagen vívida de la opresión extranjera que Dios promete quebrar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4133', 'spa', 'Barra de yugo, travesaño de madera que simboliza opresión; vara de transporte para objetos sagrados', 'El sustantivo מוֹטָה se refiere a la barra o travesaño de un yugo: la pieza de madera colocada sobre el cuello de los animales de tiro y, por poderosa metáfora bíblica, sobre el cuello de los pueblos oprimidos. Jeremías llevó físicamente barras de yugo y coyundas como acto profético simbólico (Jer 27:2), y Hananías las quebró para simbolizar la liberación (Jer 28:10, 12-13). Isaías llama a soltar las ataduras del yugo y a quebrar toda barra de opresión (Is 58:6, 9). Una única aparición en 1 Crónicas 15:15 emplea la palabra para las varas de transporte insertadas a través del Arca de la Alianza: un objeto físico distinto pero de la misma forma básica, una barra de madera llevada sobre los hombros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4134', 'spa', 'Empobrecerse, caer en la miseria; descender en estatus económico, dicho de israelitas necesitados de redención', 'Este verbo describe el proceso de empobrecimiento, empleado exclusivamente en contextos legales que abordan la red de protección social para los israelitas. Levítico 25 lo utiliza cuatro veces para introducir las leyes de redención por parentesco (v. 25), préstamos caritativos (v. 35), servidumbre por deudas (v. 39) y venta a un extranjero residente (v. 47). Levítico 27:8 lo aplica a quien es demasiado pobre para pagar la estimación de un voto. La evidencia multilingüe (spa empobrece, deu wird arm, fra devient pauvre) traduce consistentemente el sentido progresivo y resultativo de ''llegar a ser pobre'', no un estado estático.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4135a', 'spa', 'Circuncidar; por extensión, cortar o destruir, y (raramente) marchitarse o secarse', 'Circuncidar; por extensión, cortar o destruir, y (raramente) marchitarse o secarse');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4136', 'spa', 'Frente, enfrente, delante de — sustantivo y preposición que indica posición espacial directamente frente a algo', 'Frente, enfrente, delante de — sustantivo y preposición que indica posición espacial directamente frente a algo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4137', 'spa', 'Moladá, ciudad en el territorio de Simeón', 'Asentamiento asignado a la tribu de Simeón (Josué 19:2, 1 Crónicas 4:28), rehabitado después del exilio babilónico (Nehemías 11:26). Los geógrafos antiguos lo identificaron con Tel Milh, ubicado aproximadamente a cuatro horas al este de Beerseba en el Néguev. El sitio parece haber mantenido su nombre e identidad a lo largo de los siglos, desde la conquista inicial hasta el período de la restauración, convirtiéndolo en uno de los puntos más estables dentro de las posesiones territoriales de Simeón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4138', 'spa', 'Parentela, lugar de nacimiento, tierra natal; parientes, familia; descendencia, prole; el evento o circunstancias del nacimiento', 'Parentela, lugar de nacimiento, tierra natal; parientes, familia; descendencia, prole; el evento o circunstancias del nacimiento');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4142', 'spa', 'rodeado, engastado, encerrado (como gemas en su montura)', 'Forma verbal pasiva que describe objetos que están rodeados, circundados o colocados en su lugar. Aparece con mayor frecuencia en las descripciones del pectoral del sumo sacerdote, donde las piedras preciosas estaban ''engastadas'' o ''encerradas'' en monturas de oro (Éxodo 28:11, 39:6, 39:13). Ezequiel lo usa arquitectónicamente para describir puertas giratorias en la visión del templo (Ezequiel 41:24). La imagen sugiere una colocación cuidadosa dentro de un marco, ya sea para piedras preciosas en vestiduras litúrgicas o puertas en la arquitectura sagrada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4143', 'spa', 'Fundamento, cimiento, acción de establecer los cimientos de una estructura', 'Sustantivo que denota el fundamento o cimiento, así como el acto de colocar los cimientos de una edificación. En Crónicas señala el día significativo en que se pusieron los cimientos del templo de Salomón (2 Crónicas 8:16). Isaías lo emplea para describir la preciosa piedra angular que Dios pone en Sion (28:16). Ezequiel lo menciona en su visión del templo restaurado (41:8). El término subraya el punto de partida fundamental de toda construcción y, en sentido figurado, la base firme de los propósitos de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4146', 'spa', 'Fundamento, base — el soporte estructural de un edificio o, en lenguaje poético, los cimientos profundos de la tierra misma', 'El sustantivo מוֹסָד (mosad) designa un fundamento o base estructural, empleado tanto en contextos arquitectónicos como en imágenes cósmico-poéticas. En el salmo de David, los cimientos del cielo y la tierra se estremecen cuando el SEÑOR desciende (2 Sam 22:8, 16; Sal 18:7, 15), y el Cántico de Moisés advierte que el fuego de Dios arde hasta los cimientos de los montes (Deut 32:22). Isaías pregunta quién puso los cimientos de la tierra desde el principio (Isa 40:21) y llama al reconstructor de Jerusalén ''reparador de los cimientos'' (Isa 58:12). Jeremías 31:37 y Miqueas 6:2 invocan los cimientos de la tierra como testigos perdurables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4147', 'spa', 'Ataduras, cadenas, ligaduras — cadenas o cuerdas físicas; metafóricamente, todo yugo de opresión u obligación pactual', 'El sustantivo מוֹסֵר (moser) designa ataduras, cadenas o ligaduras de sujeción. Los Salmos celebran el poder de Dios para romper ataduras: el Salmo 2:3 expresa el deseo de las naciones de quebrantar las ataduras de Dios, mientras que los Salmos 107:14 y 116:16 alaban la liberación. Isaías ordena a Sion soltar las ataduras de su cuello (Isa 52:2) y advierte que ataduras más estrechas traen destrucción (Isa 28:22). Jeremías representa las ataduras del yugo como símbolo del vasallaje babilónico (Jer 27:2; 30:8), y Nahúm 1:13 promete que Dios romperá las ataduras de Asiria. Job 39:5 pregunta quién liberó al asno montés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4148', 'spa', 'Disciplina, corrección, instrucción; formación moral que abarca desde la enseñanza y la reprensión hasta el castigo correctivo.', 'Disciplina, corrección, instrucción; formación moral que abarca desde la enseñanza y la reprensión hasta el castigo correctivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4150', 'spa', 'Tiempo, lugar o asamblea señalados; principalmente en ''tienda de reunión'' (ohel moed), también para fiestas sagradas y tiempos fijados.', 'Pocas palabras hebreas cargan tanto peso institucional como מוֹעֵד. Es el vocablo detrás de la ''tienda de reunión'' donde la presencia de Dios habitaba entre Israel, y designa cada fiesta señalada del calendario litúrgico. El cognado árabe mawʿid (''cita'') y el emparentado mawsim (''estación/festival'') abarcan juntos el espectro del término. Desde Génesis 1:14, donde los luminares marcan los moadim, hasta el detallado calendario festivo de Levítico 23, מוֹעֵד ancla el culto de Israel en ritmos de tiempo y espacio sacro divinamente establecidos. Incluso en sus usos más raros, la palabra siempre transmite que esta reunión, este momento, este lugar fue decretado y no casual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4156', 'spa', 'Consejos, planes o deliberaciones, frecuentemente con connotacion negativa de maquinacion obstinada contra Dios', 'Sustantivo femenino plural que denota consejos, planes o deliberaciones. Tiene un sentido predominantemente negativo en la literatura profetica y sapiencial, refiriendose a las maquinaciones obstinadas de quienes rechazan el camino de Dios. Jeremias lo empareja con ''la terquedad de su malvado corazon'' (Jer 7:24), y Oseas advierte que los propios consejos de Israel lo consumiran (Os 11:6). Sin embargo, Proverbios 22:20 lo emplea positivamente para el buen consejo junto al conocimiento. Asi, la palabra abarca todo el espectro moral, desde el consejo sabio hasta la maquinacion rebelde, segun el contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4158', 'spa', 'Mefaat — ciudad levítica en el territorio de Rubén, posteriormente en manos moabitas', 'Mefaat fue una ciudad levítica asignada al clan de Merari dentro del territorio tribal de Rubén (Jos 13:18; 21:37; 1 Cr 6:64). Para la época de Jeremías, la ciudad había pasado a control moabita y aparece en el oráculo contra Moab (Jer 48:21). El cognado sabeo del topónimo sugiere raíces antiguas. Las variantes ortográficas en el texto hebreo (מֵפָעַת, מֵיפַעַת, מֵופָעַת) y las diversas transliteraciones entre versiones (eng Mephaath, spa Mefaat) reflejan su historia textual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4159', 'spa', 'Prodigio, señal o portento que demuestra el poder divino o sirve como símbolo profético', 'Prodigio, señal o portento que demuestra el poder divino o sirve como símbolo profético');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4161', 'spa', 'Salida, fuente, manantial; punto terminal de un límite, palabra pronunciada, lugar de origen', 'Salida, fuente, manantial; punto terminal de un límite, palabra pronunciada, lugar de origen');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4162', 'spa', 'Motsa — nombre propio de un descendiente de Caleb y de un descendiente de Saúl en la línea benjaminita', 'Motsa es el nombre de dos individuos distintos en las genealogías del Cronista. El primero es hijo de Caleb por su concubina Efa (1 Cr 2:46). El segundo pertenece a la genealogía saulida en la tribu de Benjamín, apareciendo en ambas listas paralelas de 1 Crónicas 8:36-37 y 9:42-43. La LXX los traduce de diversas formas como Mousas y Massas. Las transliteraciones en español e inglés (Motsa) son estables, mientras que el francés y el alemán conservan las formas en escritura hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4164', 'spa', 'Estrechez, angustia, constricción; lo opuesto a amplitud y libertad', 'Sustantivo que denota estrechez, angustia o constricción, lo opuesto a la amplitud y la libertad. Job lo utiliza en contraste con ''lugar amplio sin estrechez'' (36:16) y para describir las aguas congeladas en constricción (37:10). Isaías lo emplea para referirse a la antigua angustia de las tierras de Zabulón y Neftalí (9:1), que después verían una gran luz. El término captura la sensación de estar acorralado, restringido o bajo presión.');